const diffNames = [5156, 5155, 5154];
const questNames = [
  ['denofevil', 'qstsa1q1', () => _L`+${1} Skill Point`],
  ['radamentslair', 'qstsa2q1', () => _L`+${1} Skill Point`],
  ['thegoldenbird', 'qstsa3q4', () => _L`+${20} Maximum Life`],
  ['lamessenstome', 'qstsa3q1', () => _L`+${5} Attribute Points`],
  ['thefallenangel', 'qstsa4q1', () => _L`+${2} Skill Points`],
  ['prisonofice', 'qstsa5q3', () => _L`+${10} All Resistances`],
];

function QuestList() {
  const quests = Store.useProfile(profile => profile.quests);
  const dispatch = Store.useDispatch();
  const onCheck = React.useCallback((index, id, value) => dispatch.setProfile(profile => {
    const quests = profile.quests?.slice() || [];
    quests[index] = {...quests[index]};
    quests[index][id] = value;
    return profileUpdateAttributes({...profile, quests});
  }), [dispatch]);
  const onCheckAct = React.useCallback((index, value) => dispatch.setProfile(profile => {
    const quests = profile.quests?.slice() || [];
    quests[index] = {...quests[index]};
    for (const [id] of questNames) {
      quests[index][id] = value;
    }
    return profileUpdateAttributes({...profile, quests});
  }), [dispatch]);
  return (
    <div className="d2p-GroupBox">
      <span className="d2p-title"><span>{_L`Quests`}</span></span>
      <table className="d2p-QuestList">
        <thead>
          <tr>
            <th>Name</th>
            {[0, 1, 2].map(index => <th key={index}>{Locale.istrings[diffNames[index]]}</th>)}
          </tr>
        </thead>
        <tbody>
          {questNames.map(([id, name, bonus]) => (
            <tr key={id}>
              <td>
                <span>{Locale.strings[name]}</span>
                <span className={`d2-color-${Color.GRAY}`}>{bonus()}</span>
              </td>
              {[0, 1, 2].map(index => (
                <td key={index}>
                  <input type="checkbox" checked={!!quests?.[index]?.[id]} onChange={e => onCheck(index, id, !!e.target.checked)}/>
                </td>
              ))}
            </tr>
          ))}
          <tr>
            <td/>
            {[0, 1, 2].map(index => (
              <td key={index} className="d2p-act-toggle">
                <span onClick={() => onCheckAct(index, true)}>All</span>/
                <span onClick={() => onCheckAct(index, false)}>None</span>
              </td>
            ))}
          </tr>
        </tbody>
      </table>
    </div>
  );
}

