function AttributesList() {
  // const [icon, setIcon] = React.useState();
  // const alive = React.useRef(true);
  // const gfx = React.useContext(GameContext).gfx;
  // React.useEffect(() => {
  //   if (!gfx.hd) {
  //     alive.current = true;
  //     getCommonImage('level').then(icon => alive.current && setIcon(icon));
  //     return () => alive.current = false;
  //   }
  // }, [gfx]);

  const finalStats = Store.useSelector(selectStats);
  const stats = Store.useProfile(profile => profile.stats);
  const maxPoints = Store.useProfile(profileMaxAttributes);
  const spentPoints = Object.values(stats).reduce((sum, value) => sum + value, 0);
  const dispatch = Store.useDispatch();
  const onChange = React.useCallback((stat, value) => dispatch.setProfile(profile => {
    const stats = {...profile.stats};
    const maxPoints = profileMaxAttributes(profile);
    const spentNow = Object.values(stats).reduce((sum, value) => sum + value, 0);
    const spentNext = spentNow - (stats[stat] || 0) + value;
    if (spentNext > maxPoints) {
      value -= (spentNext - maxPoints);
      if (value < (stats[stat] || 0)) return profile;
    }
    stats[stat] = value;
    return {...profile, stats};
  }), [dispatch]);

  return (
    <div className="d2p-GroupBox">
      <span className="d2p-title"><span>{_L`Attributes (${Math.max(0, maxPoints - spentPoints)} remaining)`}</span></span>
      <table className="d2p-AttributesList">
        <tbody>
          {statNames.map(([key, name, stat, req]) => (
            <tr key={key}>
              <td>{Locale.strings[name]} +</td>
              <td><NumberInput min={0} max={maxPoints - spentPoints + (stats[key] || 0)} value={stats[key] || 0} onChange={value => onChange(key, value)}/></td>
              <td className={req && finalStats.player[req] > finalStats.player.base[stat] ? `d2-color-${Color.RED}` : ''}>
                ({finalStats.player.base[stat]}{!!(finalStats.player[req] > finalStats.player.base[stat]) && ` / ${finalStats.player[req]}`})
              </td>
            </tr>
          ))}
        </tbody>
      </table>
    </div>
  );
}

// Error boundary for SkillTree
class SkillTreeErrorBoundary extends React.Component {
  constructor(props) {
    super(props);
    this.state = { hasError: false, error: null };
  }

  static getDerivedStateFromError(error) {
    return { hasError: true, error };
  }

  componentDidCatch(error, errorInfo) {
    console.error('SkillTree Error:', error, errorInfo);
  }

  render() {
    if (this.state.hasError) {
      return (
        <div style={{ padding: '20px', background: '#2c1810', color: '#ff6b6b', borderRadius: '5px', margin: '10px' }}>
          <h4>❌ Skill Tree Error</h4>
          <p>Error: {this.state.error?.message || 'Unknown error in skill tree'}</p>
          <button 
            onClick={() => this.setState({ hasError: false, error: null })}
            style={{ background: '#d4af37', color: '#2c1810', border: 'none', padding: '5px 10px', borderRadius: '3px', cursor: 'pointer' }}
          >
            Try Again
          </button>
        </div>
      );
    }

    return this.props.children;
  }
}

export default React.memo(function CharacterPane() {
  return (
    <div className="d2p-CharacterPane">
      <SkillTreeErrorBoundary>
        <SkillTree/>
      </SkillTreeErrorBoundary>
      <div className="d2p-after-tree">
        <QuestList/>
        <AttributesList/>
      </div>
    </div>
  );
});
