export function hd_applyTint(bits, size, tint, name) {
  const tablei = Math.floor(tint / 21), colori = tint % 21;
  if (tablei < 9) HEAPF32.set(Data.colorRangeOverride[name] || tintTable[Math.floor(tint / 21)], 20);
  HEAPF32.set(tablei < 9 ? (Data.colorTransformOverride[`${name}:${tintName[tint % 21]}`] || tintColor[tint % 21]) : tintExtra[colori], 26);
  HEAPU8.set(bits, 256);

  const offset = (tablei < 9 ? calculator.palette(size) : calculator.tint(size));

  return HEAPU8.subarray(offset, offset + size * 4);
}
