import React from 'react';

import Locale from '../../data/locale';
import Store from '../../store';

import './ImportPane.scss';
import { parseFile } from '../../logic/binary';
import { OverlayContext } from '../../ui/utils/OverlayManager';
import { stateAddProfile } from '../../logic/stateReducers';
import { ErrorPopup } from '../../ui/utils/Overlay';
import EditingContext from '../../store/editingContext';

const _L = Locale("ui-import");

export default function ImportSection() {
  const dispatch = Store.useDispatch();
  const overlays = React.useContext(OverlayContext);
  const editingDispatch = EditingContext.useDispatch();
  const onChange = React.useCallback(e => {
    if (e.target.files.length > 0) {
      const file = e.target.files[0];
      const ext = file.name.split('.').pop().toLowerCase();
      if(ext === 'd2s') {
        parseFile(e.target.files[0]).then(
        result => {
          dispatch.setState(state => stateAddProfile(state, result.profile, result.items));
          editingDispatch({type: "equipment"});
        },
        //error => overlays.async(<ErrorPopup title={_L`Failed to parse file`} message={error.message}/>)
      );
      } 
      else if (ext === 'json') {
        const reader = new FileReader();
          reader.onload = () => {
            try {
              const data = JSON.parse(reader.result);
              if (data.data.profiles && data.data.profiles.length > 0) {
                for (let i = 0; i < data.data.profiles.length; i++) {
                  const profile = data.data.profiles[i];
                  dispatch.setState(state => stateAddProfile(state, profile, data.data.items));
                }
              }
              else if (data.data.profiles.length === 1) {
                dispatch.setState(state => stateAddProfile(state, data.data.profiles[0], data.data.items));
              }
              editingDispatch({type: "equipment"});
            } catch (error) {
              overlays.async(<ErrorPopup title={_L`Failed to parse file`} message={error.message}/>);
            }
        };
        reader.readAsText(file);
        }
        else {
          overlays.async(<ErrorPopup title={_L`Unsupported file`} message={`File type .${ext} is not supported.`}/>);
        }
    }
  }, [dispatch, overlays, editingDispatch]);

  return (
    <div className="d2p-SectionContent d2p-section-import">
      <div className="d2p-description">
        <p>Save files are located in your user folder, under <span style={{fontFamily: 'monospace', backgroundColor: '#111', padding: '0 3px'}}>Saved Games/Diablo II Resurrected</span></p>
      </div>
      <div>
        <label className="d2p-file">
          <input style={{display: "none"}} type="file" onChange={onChange} accept={".d2s,.json"} multiple={false}/>
          Select a file, or drop it onto the page.
        </label>
      </div>
    </div>
  );
}
