const _L = Locale("ui-character");

const GridLeft = 15;
const GridTop = 14;
const GridRow = 68;
const GridCol = 69;
const GridPage = 233;

const GridLeftHD = 49;
const GridTopHD = 56;
const GridColHD = 97;
const GridRowHD = 66;

export function checkPrereq(id, skills) {
  if (!Data.skills || !id || !skills) {
    return false;
  }
  
  function check(id) {
    if (!id) return true;
    const sk = Data.skills[id];
    return !sk || skills[sk.id];
  }
  
  const skill = Data.skills[id];
  if (!skill) return false;
  
  return check(skill.reqskill1) && check(skill.reqskill2) && check(skill.reqskill3);
}
export const questPoints = quests => quests?.reduce((sum, q) => {
  if (q.denofevil) sum += 1;
  if (q.radamentslair) sum += 1;
  if (q.thefallenangel) sum += 2;
  return sum;
}, 0) || 0;

export const gridPos = (page, row, col, hd) => {
  if (hd && page < 0) {
    return {
      left: GridLeftHD + (col - 1) * GridColHD,
      top: GridTopHD + (row - 1) * GridRowHD,
    };
  } else {
    if (page < 0) page = 3;
    return {
      left: GridLeft + (3 - page) * GridPage + (col - 1) * GridCol,
      top: GridTop + (row - 1) * GridRow + (row >= 5 ? 1 : 0),
    };
  }
}


function SkillLevelTip({ id }) {
  const stats = Store.useSelector(selectStats).player;
  const stat = {
    name: _L`Level`,
    value: stats => stats.skills[id],
    tooltip: [
      `{sources:skills.${id}}`,
    ],
  };
  return <StatTooltip stat={stat} stats={stats} skills unit="player"/>;
}

export function SkillButton({ id, stats, onHover, onPressed, canLevel, bypassLevel, onChange, recording, noPage, hd, ...props }) {
  const [editing, setEditing] = React.useState(false);
  const [pressed, setPressed] = React.useState(false);
  const ctrlKey = useCtrl();

  const skill = Data.skills?.[id];
  const desc = skill && Data.skillDesc?.[skill.skilldesc];

  const level = stats.base_skills[id] || 0;
  const canLevelThis = canLevel && checkPrereq(id, stats.base_skills) && (bypassLevel || stats.level >= skill.reqlevel + level);

  React.useEffect(() => {
    if (recording || !onChange) setEditing(false);
  }, [recording, onChange]);

  const onFocus = React.useCallback(() => !recording && !!onChange && (level || canLevelThis) && setEditing(true),
    [level, canLevelThis, recording, onChange]);
  const onBlur = React.useCallback(() => setEditing(false), []);
  const inputRef = React.useRef();
  React.useEffect(() => {
    if (inputRef.current) inputRef.current.focus();
  }, [editing]);

  const hasDepends = React.useMemo(() => Object.entries(stats.base_skills).some(([sid, level]) => {
    if (!level) return false;
    const skill = Data.skills[sid];
    const nid = parseInt(id);
    return (skill.reqskill1 === nid || skill.reqskill2 === nid || skill.reqskill3 === nid);
  }), [id, stats]);

  props = {...props};

  const events = {};
  events.onClick = React.useCallback((e) => {
    try {
      if (level < 20 && canLevelThis && onChange) {
        onChange(id, level + 1);
      }
    } catch (error) {
      console.error('Error in SkillButton onClick:', error);
    }
  }, [id, onChange, level, canLevelThis]);
  events.onContextMenu = React.useCallback(e => {
    try {
      e.preventDefault();
      if (level > 0 && !recording && onChange) {
        if (level === 1 && hasDepends) return;
        onChange(id, level - 1);
      }
    } catch (error) {
      console.error('Error in SkillButton onContextMenu:', error);
    }
  }, [id, onChange, level, hasDepends, recording]);
  props.onMouseOver = React.useCallback(() => onHover(id), [id, onHover]);
  props.onMouseOut = React.useCallback(() => onHover(null), [onHover]);
  
  events.onMouseDown = React.useCallback(() => {
    if (level < 20 && canLevelThis) {
      setPressed(true);
    }
  }, [level, canLevelThis]);
  props.onDragStart = React.useCallback(e => e.preventDefault(), []);
  React.useEffect(() => {
    if (!onPressed) {
      return;
    } if (pressed) {
      onPressed(id);
      const handler = () => setPressed(false);
      document.addEventListener('mouseup', handler);
      return () => document.removeEventListener('mouseup', handler);
    } else {
      onPressed(null);
    }
  }, [pressed, onPressed, id]);

  if (onChange) {
    Object.assign(props, events);
  }

  const onInput = React.useCallback(value => {
    if (value > 20) value = 20;
    if (hasDepends && value < 1) value = 1;
    onChange(id, value);
  }, [id, onChange, hasDepends]);

  // Проверяем наличие данных после всех хуков
  if (!Data.skills || !Data.skillDesc || !id || !skill || !desc) {
    return null;
  }
  const page = desc.skillpage, row = desc.skillrow, col = desc.skillcolumn;
  if (!page || !row || !col) return null;

  const totalLevel = (ctrlKey ? level : (stats.skills[id] || 0));

  return (
    <div className="d2p-SkillTreeButton d2p-no-link" style={gridPos(noPage ? -1 : page, row, col, hd)}>
      <Tooltip tooltip={<SkillLevelTip id={id}/>} disabled={!stats.skills[id]} align={editing ? "left" : null}>
        <div className="d2p-skill-level" onClick={onFocus}>
          {!!(!editing && hd && totalLevel) && <span className={`d2-color-${totalLevel > level ? Color.BLUE : Color.WHITE}`}>{totalLevel}</span>}
          {!!editing && <NumberInput min={hasDepends ? 1 : 0} max={20} value={level} onChange={onInput} onBlur={onBlur} ref={inputRef}/>}
        </div>
      </Tooltip>
      <D2SkillTooltip id={id} canLevel={canLevelThis} full>
        <div className="d2p-skill-icon" {...props}/>
      </D2SkillTooltip>
    </div>
  );
}

