export function SkillSlider({ recording, setRecording, setHighlight }) {
  const dispatch = Store.useDispatch();
  const skillProgression = Store.useProfile(profile => profile.skillProgression);
  const skillPos = Store.useProfile(profile => profile.skillPos) || 0;

  const onRecord = React.useCallback(() => {
    if (recording) {
      setRecording(false);
    } else {
      setRecording(true);
      dispatch.setProfile(profile => {
        const skills = profileSelectSkills(profile);
        return {...profile, skills, skillProgression: [], skillPos: 0};
      });
    }
  }, [recording, setRecording, dispatch]);

  const leftDisabled = recording || !skillProgression?.length || !skillPos;
  const rightDisabled = recording || !skillProgression?.length || skillPos >= skillProgression.length;
  const sliderDisabled = recording || !skillProgression?.length;

  const onSlider = React.useCallback(value => !recording && dispatch.setProfile(profile => {
    const length = profile.skillProgression?.length;
    if (!length) return profile;
    value = Math.min(length, Math.max(0, value));
    if (value === profile.skillPos) return profile;
    return {...profile, skillPos: value};
  }), [dispatch, recording]);
  const onLeft = React.useCallback(() => onSlider(skillPos - 1), [onSlider, skillPos]);
  const onRight = React.useCallback(() => onSlider(skillPos + 1), [onSlider, skillPos]);

  const lastPos = React.useRef(skillPos);
  React.useEffect(() => {
    const delta = skillPos - (lastPos.current || 0);
    lastPos.current = skillPos;
    if (setHighlight && !recording && skillProgression?.length && delta) {
      const id = skillProgression[delta < 0 ? skillPos : skillPos - 1];
      if (!id) return;
      setHighlight({id, delta});
      const timeout = setTimeout(() => setHighlight(null), 500);
      return () => {
        setHighlight(null);
        clearTimeout(timeout);
      };
    }
  }, [skillPos, skillProgression, recording, setHighlight]);

  return (
    <div className="d2p-SkillSlider">
      {!!setRecording && (
        <Tooltip tooltip={recording ? _L`Stop recording` : _L`Record skill progression`}>
          <div className={classNames("d2p-button d2p-record", {"d2p-active": recording})} onClick={onRecord}/>
        </Tooltip>
      )}
      <div className={classNames("d2p-button d2p-move d2p-left", {"d2p-disabled": leftDisabled})} onMouseDown={onLeft}/>
      <Slider min={0} max={skillProgression?.length || 0} step={1} value={skillPos} onChange={onSlider}
        disabled={sliderDisabled} className={classNames({"d2p-disabled": sliderDisabled})}/>
      <div className={classNames("d2p-button d2p-move d2p-right", {"d2p-disabled": rightDisabled})} onMouseDown={onRight}/>
    </div>
  );
}
