import Locale from '../../data/locale';
import { stateFix, stateIsEmpty } from '../../logic/stateReducers';
import React from 'react';

import Store from '../../store';
import EditingContext from '../../store/editingContext';
//import { exportAllProfiles } from 'logic/import';
import { usePersistentState } from '../../utils';
import { _R } from '../../utils/format';

const _L = Locale();

export default React.memo(function AutoSave() {
  const [backup, setBackup] = usePersistentState("d2p-stateBackup", null);
  const [changed, setChanged] = EditingContext.useState("profileChanged", false);

  const state = Store.useState();
  const isEmpty = stateIsEmpty(state);

  const dispatch = Store.useDispatch();

  React.useEffect(() => {
    if (!stateIsEmpty(state)) {
      const handle = setTimeout(() => {
        setBackup(state.imported ? null : state);
      }, 1000);
      return () => clearTimeout(handle);
    }
  }, [setBackup, state]);

  React.useEffect(() => {
    if (!changed && !isEmpty) {
      setChanged(true);
    }
  }, [setChanged, changed, isEmpty]);

  const onRestore = React.useCallback(() => {
    if (backup && backup.profiles) {
      const state = {...backup};
      delete state.auto;
      dispatch.setState(stateFix(state));
    }
  }, [dispatch, backup]);

  const onClear = React.useCallback(() => {
    setBackup(null);
  }, [setBackup]);

  React.useEffect(() => {
    if (backup && backup.auto) {
      onRestore();
      setBackup({...backup, auto: false});
    }
  }, [backup, onRestore, setBackup]);

  if (!backup || !backup.profiles || changed) {
    return null;
  }

  return (
    <div className="d2p-RestoreSession">
      {_L`Restore last session?`}{_R` ${<span onClick={onRestore}>{_L`Yes`}</span>} / ${<span onClick={onClear}>{_L`No`}</span>}`}
    </div>
  );
});
