import { faBold, faHeading, faImage, faItalic, faLink, faListOl, faListUl, faQuoteRight, faStrikethrough } from '@fortawesome/free-solid-svg-icons';
import { FontAwesomeIcon } from '@fortawesome/react-fontawesome';
import React from 'react';
import Resizable from '../../ui/resizable';

function ToolbarButton({ params, onAction }) {
  const onClick = React.useCallback(() => params.action && onAction(params.action), [params, onAction]);
  if (params.separator) {
    return <li className="d2p-separator"/>;
  }
  return (
    <li className={params.className}>
      <button title={params.title + (params.hotkey ? ` (${params.hotkey})` : "")} onClick={onClick}>
        {params.icon}
      </button>
    </li>
  );
}

export function getSelection(editor) {
  if (!editor) return {start: 0, end: 0, text: ""};
  const start = editor.selectionStart;
  const end = editor.selectionEnd;
  return {start, end, text: editor.value.substring(start, end)};
}

export function replaceSelection(editor, selection, text, offsetStart, offsetEnd) {
  if (!editor) return;
  editor.value = editor.value.substring(0, selection.start) + text + editor.value.substring(selection.end);
  editor.setSelectionRange(selection.start + (offsetStart || 0), selection.start + (offsetEnd == null ? text.length : offsetEnd));
  editor.focus();
}

export function replaceLinePrefix(editor, selection, match, prefix) {
  editor.focus();
  const pos = editor.value.lastIndexOf("\n", selection.start - 1) + 1;
  const line = editor.value.substring(pos);
  const m = line.match(match);
  let delta = 0;
  if (m) {
    editor.value = editor.value.substring(0, pos) + editor.value.substring(pos + m[0].length);
    delta = -m[0].length;
  } else {
    editor.value = editor.value.substring(0, pos) + prefix + editor.value.substring(pos);
    delta = prefix.length;
  }
  editor.setSelectionRange(selection.start + delta, selection.end + delta);
}

