export function writeCharacter(state, profile, items, name, version) {
  if (version < 96 || version > 105) throw Error('unsupported version');
  const D2R = (version >= 97);

  const writer = new BitWriter();

  // ================= HEADER =================
  writer.writeUInt32(0xaa55aa55);
  writer.writeUInt32(version);
  // padding до 40 байт
  //padBytes(writer, 40);
  writer
    .writeUInt32(0x0) //0x0008 (filesize. needs to be writen after all data)
    .writeUInt32(0x0); //0x000c (checksum. needs to be calculated after all data writer)
  if (version >= 105) {
    writer.writeArray(new Uint8Array([0x00, 0x00, 0x00, 0x00])); // 0x0010 (4 bytes for v105)
  } else if (version > 0x61) {
    writer.writeArray(new Uint8Array(Array(20).fill(0))); // 0x0010
  } else {
    writer.writeArray(new Uint8Array([0x00, 0x00, 0x00, 0x00])) //0x0010
    writer.writeString(name || profile.name, 16);
  }

  profile.header = header.header;
  // profile.header.version = version;
  // profile.header.status = {};
  // profile.header.status.expansion = true;

  const statusForWrite = version >= 105
    ? { ...profile.header.status, expansion: false }
    : profile.header.status;
  writer
    .writeArray(writeStatus(statusForWrite)) //0x0024 (v99) or 0x0014 (v105)
    .writeUInt8(profile.header.progression) //0x0025 (v99) or 0x0015 (v105)
    .writeUInt16(profile.header.active_arms) //0x0026

  writer.writeUInt8(Data.classes.indexOf(profile.class));

  writer
    .writeArray(new Uint8Array([0x10, 0x1e])) //0x0029
    .writeUInt8(profile.level) //0x002b
    .writeArray(new Uint8Array([0x00, 0x00, 0x00, 0x00])) //0x002c
    .writeUInt32(profile.header.last_played) //0x0030
    .writeArray(new Uint8Array([0xff, 0xff, 0xff, 0xff])) //0x0034
    .writeArray(_writeAssignedSkills(profile.header.assigned_skills)) //0x0038
    .writeUInt32(_skillId(profile.header.left_skill)) //0x0078
    .writeUInt32(_skillId(profile.header.right_skill)) //0x007c
    .writeUInt32(_skillId(profile.header.left_swap_skill)) //0x0080
    .writeUInt32(_skillId(profile.header.right_swap_skill)) //0x0084
    .writeArray(_writeCharMenuAppearance(profile.header.menu_appearance)) //0x0088 [char menu appearance]
    .writeArray(_writeDifficulty(profile.header.difficulty)) //0x00a8
    .writeUInt32(profile.header.map_id) //0x00ab
    .writeArray(new Uint8Array([0x00, 0x00])); //0x00af [unk = 0x0, 0x0]
    if (profile.merc) {
      writer.writeUInt16(profile.header.dead_merc) //0x00b1
      //parseInt((Math.random() * 0xffffffff) >>> 0, 16)
      writer.writeUInt32(parseInt(profile.header.merc_id, 16)) //0x00b3
      writer.writeUInt16(profile.mercName || 0) //0x00b7
      writer.writeUInt16(profile.merc || 0) //0x00b9
      writer.writeUInt32(xp[profile.mercLevel - 1 ] || 0); //0x00bb
    } else {
      writer.writeUInt16(profile.header.dead_merc);
      writer.writeUInt32(parseInt("0", 16));
      writer.writeUInt16(0);
      writer.writeUInt16(0);
      writer.writeUInt32(0); //0x00bb
    }
  //padToOffset(writer, 179);

  if (version >= 105) {
    const extBlock1 = new Uint8Array(124);
    extBlock1[73] = 0x03; // v105 expansion flag (0x03=expansion, 0x01=classic)
    // TODO: populate item reference entries at bytes 76+ for equipped items
    writer
      .writeArray(extBlock1) //0x00af: 73 zeros + expansion flag + item ref section
      .writeString(name || profile.name || '', 16) //0x012b
      .writeArray(new Uint8Array(88)); //0x013b
  } else if (version > 97) {
    writer
      .writeArray(new Uint8Array(76)) //0x00bf [unk]
      .writeString(name || profile.name || '', 16) //0x010b
      .writeArray(new Uint8Array(52)); //0x011b [unk]
  } else {
    writer
      .writeArray(new Uint8Array(140)) //0x00bf [unk]
      .writeUInt32(0x1); //0x014b [unk = 0x1, 0x0, 0x0, 0x0]
  }

  // ================= QUESTS =================
  writer
    .writeString("Woo!", 4) //0x014f [quests = 0x57, 0x6f, 0x6f, 0x21 "Woo!"]
    .writeArray(new Uint8Array([0x06, 0x00, 0x00, 0x00, 0x2a, 0x01])) //0x0153 [unk = 0x6, 0x0, 0x0, 0x0, 0x2a, 0x1]
    .writeArray(_writeQuests(profile.header.quests_normal)) //0x0159
    .writeArray(_writeQuests(profile.header.quests_nm)) //0x01b9
    .writeArray(_writeQuests(profile.header.quests_hell)) //0x0219
    .writeString("WS", 2) //0x0279 [waypoint data = 0x57, 0x53 "WS"]
    .writeArray(new Uint8Array([0x01, 0x00, 0x00, 0x00, 0x50, 0x00])) //0x027b [unk = 0x1, 0x0, 0x0, 0x0, 0x50, 0x0]
    .writeArray(_writeWaypointData(profile.header.waypoints)) //0x0281
    .writeArray(new Uint8Array([0x01, 0x77])) //0x02c9 [npc header = 0x01, 0x77 ".w"]
    .writeUInt16(0x34) //0x02ca [npc struct length]
    .writeArray(_writeNPCData(profile.header.npcs)); //0x02cc [npc introduction data... unk]

  //padToOffset(writer, 765);
  //console.log("offset before stats:", writer.offset / 8); // 765
  // ================= STATS =================
  writer.writeArray(writeCharacterStats(state, profile));

  // ================= SKILLS =================
  writer.writeUInt16(0x6669);
  const classId = Data.classes.indexOf(profile.class);
  const skillBases = [6, 36, 66, 96, 126, 221, 251, 373];
  const skillBase = skillBases[classId] ?? (classId < 5 ? classId * 30 + 6 : (classId - 5) * 30 + 221);
  for (let i = 0; i < 30; i++) {
    const lvl = profile.skills?.[i + skillBase] || 0;
    //console.log('i + skillBase ', i + skillBase, 'lvl ', lvl);
    writer.writeUInt8(lvl);  
  }
  writer.align();

  // ================= ITEMS =================
  //console.log("items offset =", writer.offset / 8);
  writer.writeArray(writeItemList(profile, items, version, false));

  //================= CORPSE =================
  writer.writeUInt16(0x4d4a);
  //writer.writeString("JM", 2);   // JM header
  //TODO items
  writer.writeUInt16(0);

  //================= MERC ITEMS =================
  writer.writeUInt16(0x666a);
  writer.writeArray(writeItemList(profile, items, version, true));

  //================= IRON GOLEM =================
  writer.writeUInt16(0x666b);
  //TODO items
  writer.writeUInt8(0);

  //================= V105 EXTRA SECTIONS =================
  if (version >= 105) {
    writer.writeUInt16(1);        // unknown flag/count
    writer.writeUInt16(0x666c);   // new v105 section marker
    writer.writeUInt16(0);        // section data (empty)
  }

  fixHeader(writer);

  return writer.toArray();
}

// ===== STATS =====
function writeCharacterStats(state, profile) {
  const writer = new BitWriter();
  //const base = Data.charStats[profile.class];
  const stats = profile.stats || {};
  const maxPoints = profileMaxAttributes(profile);
  const spentPoints = Object.values(stats).reduce((sum, value) => sum + value, 0);
  //const charLevel = profile.level;
  const skills = profile.skills || {};
  const spent_points = Object.values(skills).reduce((sum, x) => sum + x, 0);
  const max_points0 = profile.level - 1 + questPoints(profile.quests);
  //const max_points = (bypassLevel ? 99 : charLevel) - 1 + quest_points;
  const playerStats = selectStats(state)['player'];

  writer.writeString("gf", 2);
  const statMap = [
    { key: "strength", value: playerStats.base.strength},
    { key: "energy", value: playerStats.base.energy},
    { key: "dexterity", value: playerStats.base.dexterity},
    { key: "vitality", value: playerStats.base.vitality},
    { key: "statpts", value: Math.max(0, maxPoints - spentPoints) },
    { key: "newskills", value: Math.max(0, max_points0 - spent_points)},
    { key: "hitpoints", value: playerStats.base.maxhp },
    { key: "maxhp", value: playerStats.base.maxhp},
    { key: "mana", value: playerStats.base.maxmana},
    { key: "maxmana", value: playerStats.base.maxmana},
    { key: "stamina", value: playerStats.base.maxstamina},
    { key: "maxstamina", value: playerStats.base.maxstamina},
    { key: "level", value: profile.level || 1 },
    { key: "experience", value: xp[profile.level - 1]},
    { key: "gold", value: 990000 },
    { key: "goldbank", value: 2500000 }
  ];

  for (let i = 0; i < statMap.length; i++) {
    const s = statMap[i];
    const stat = Data.itemStatCost[s.key];
    if (!stat) { console.warn('stats not found: ', s.key); continue}
    let value = s.value || 0;
    if (i >= 6 && i <= 11) value <<= 8;
    writer.writeUInt16(stat.id, 9);
    writer.writeUInt32(value, stat.csvbits ?? 0);
  }

  writer.writeUInt16(0x1FF, 9);
  writer.align();
  return writer.toArray();
}

// ===== ITEMS =====
function writeItemList(profile, allItems, version, merc) {
  const entries = [], //used = new Set(), 
  items = new Set(Object.keys(allItems));
  const socketed = new Set();
  for (const item of Object.values(allItems)) {
    if (item.socketedItems) {
      for (const s of item.socketedItems) socketed.add(s);
    }
  }

  const push = (id, loc) => {
    if (!id || !items.has(id) //|| used.has(id)
    ) return;
    if (socketed.has(id)) return; 
    //used.add(id);
    entries.push({ item: { ...allItems[id], id }, ...loc });
  };

  if (merc) {
    for (const slot in profile.mercItems || {}) {
      const id = profile.mercItems[slot];
      push(id, { location: 'merc', loc: 1, equip: bodyLocMap[slot], x: 0, y: 0, storage: 2})
    }
  } else {
    for (const slot in profile.items || {}) {
      const id = profile.items[slot];
      //items.has(id) //&& !used.has(id)
      // ?
      push(id, { location: 'body', loc: 1, equip: bodyLocMap[slot], x: 0, y: 0, storage: 1})
      //: delete profile.items[slot];
    }
    (profile.inventory || []).forEach((id, i) =>
      push(id, { location: 'inventory', loc: 0, equip: 0, x: i % 10, y: (i / 10) | 0 , storage: 1})
    );
    (profile.cube || []).forEach((id, i) =>
      push(id, { location: 'cube', loc: 4, equip: 0, x: i % 3, y: (i / 3) | 0 , storage: 3})
    );
    const stashColumns = Data.info?.stash?.columns || 10;
    (profile.stash || []).forEach((id, i) =>
      push(id, { location: 'stash', loc: 0, equip: 0, x: i % stashColumns, y: (i / stashColumns) | 0 , storage: 5})
    );
  }  

  const writer = new BitWriter();
  writer.writeString("JM", 2);   // JM header
  //writer.writeUInt16(0x4d4a);
  writer.writeUInt16(entries.length);
  for (const e of entries) {
    writer.writeArray(writeItem(e.item, e, allItems, version));
  }

  return writer.toArray();
}

function writeItem(item, entry, allItems, version) {
  const writer = new BitWriter();
  if (version <= 96) {
    writer.writeString("JM", 2);
  }
  // ================= FLAGS =================
  writer.writeBits(0, 4);
  //writer.writeBits(new Uint8Array(4), 4);    
  writer.writeBit(item.unidentified ? 0 : 1);   // identified
  writer.writeBits(0, 6);
  //writer.writeBits(new Uint8Array(6), 6);
  writer.writeBit(item.sockets > 0 ? 1 : 0);
  writer.writeBits(0, 4);
  //writer.writeBits(new Uint8Array(4), 4);
  writer.writeBits(item.ear ? 1 : 0, 1);
  writer.writeBits(0, 4);
  //writer.writeBits(new Uint8Array(4), 4);
  writer.writeBit(item.simple ? 1 : 0);
  writer.writeBit(item.ethereal ? 1 : 0);
  writer.writeBit(1); // justsaved = 1
  //writer.writeBits(new Uint8Array([1]), 1);
  writer.writeBit(item.personalized ? 1 : 0);
  writer.writeBit(0);
  //writer.writeBits(new Uint8Array(1), 1);
  const runeword = item.unique?.startsWith('runeword');
  //console.log("runeword", runeword)
  writer.writeBit(runeword ? 1 : 0);
  writer.writeBits(0, 5);
  //writer.writeBits(new Uint8Array(5), 5);
  if (version <= 96) {
    //TODO
    // 0 = pre-1.08; 1 = 1.08/1.09 normal; 2 = 1.10 normal; 100 = 1.08/1.09 expansion; 101 = 1.10 expansion
    writer.writeUInt16(parseInt('100', 10), 10);
  } else if (version == 97 || version == 98 || version == 99) {
    writer.writeUInt16(parseInt('101', 2), 3);
  } else if (version == 105) {
    //writer.writeUInt16(parseInt('100', 2), 3);
    writer.writeUInt16(0b100, 3);
  }

  // ================= LOCATION =================
  writer.writeUInt8(entry.loc, 3);
  writer.writeUInt8(entry.equip, 4);
  writer.writeUInt8(entry.x, 4);
  writer.writeUInt8(entry.y, 4);
  writer.writeUInt8(entry.storage, 3);

  //TODO
  //if (item.is_ear) {
  //   writer.writeUInt8(item.ear_attributes.class, 3);
  //   writer.writeUInt8(item.ear_attributes.level, 7);
  //   const name = item.ear_attributes.name.substring(0, 15);
  //   for (let i = 0; i < name.length; i++) {
  //     writer.writeUInt8(name.charCodeAt(i) & 0x7f, 7);
  //   }
  //   writer.writeUInt8(0x00, 7);  
  // }
  //else
  // ================= BASE (HUFFMAN) =================
  if (version <= 96) {
    writer.writeString(item.base + ' ', 4);
  } else {
    const base = item.base + ' ';
    for (const c of base) {
      const h = HUFFMAN_LOOKUP[c];
      if (!h) throw new Error(`No huffman for '${c}'`);
      writer.writeUInt16(h.v, h.l);
      // for (let i = 0; i < h.l; i++) {
      //   writer.writeBit((h.v >> i) & 1);
      // }
    }
  }
  
  //TODO for rune containers
  // if (item.categories?.includes("Quest")) {
  //   const difficulty = item.quest_difficulty || 0;
  //   writer.WriteUInt16(difficulty + constants.magical_properties[356].sA, constants.magical_properties[356].sB);
  //   bits = 1;
  // }

  // if (version === 105 )
  //   writer.writeUInt8(item.sockets || 0, 4);
  // else 
  
  writer.writeUInt8(item.sockets || 0, item.simple ? 1 : 3);

  //console.log(item);
  if (!item.simple) {
    writer.writeUInt32(item.id || 0, 32);
    writer.writeUInt8(item.ilvl, 7);
    let quality = runeword ? 2 : qualityToFileBits[item.quality] || 0;
    writer.writeUInt8(quality, 4);
    if (item.iconIndex) {
      writer.writeUInt8(1, 1);
      writer.writeUInt8(item.iconIndex, 3);
    } else {
      writer.writeUInt8(0, 1);
    }
    //item.class_specific
    writer.writeUInt8(0, 1);

    let mp = 0, ms = 0;
    switch (item.quality) {
      case Quality.LOW:
        writer.writeUInt8(0, 3);
        break;
      case Quality.NORMAL:
        break;
      case Quality.SUPERIOR:
        writer.writeUInt8(0, 3);
        break;
      case Quality.MAGIC:
        for (const k in item.mods || {}) {
          if (!mp && k.includes('mp')) mp = +k.slice(2);
          else if (!ms && k.includes('ms')) ms = +k.slice(2);
        }
        writer.writeUInt16(mp || 0, 11);
        writer.writeUInt16(ms || 0, 11);
        break;
      case Quality.SET:
        writer.writeUInt16(+item.unique?.replace('set', '') || 0, 12);
        break;
      case Quality.UNIQUE:
        writer.writeUInt16(+item.unique?.replace('unique', '') || 0, 12);
        break;
      //case Quality.RUNEWORD:
      //   writer.writeUInt16(+item.unique?.replace('runeword', '') || 0, 12);
      //   writer.writeUInt8(0, 4);
      //   break;  
      case Quality.RARE:
      case Quality.CRAFTED:
        const mods = Object.keys(item.mods || {});
        mp = mods.filter(k => k.startsWith('mp')).map(k => +k.slice(2));
        ms = mods.filter(k => k.startsWith('ms')).map(k => +k.slice(2));
        const { rarePrefix, rareSuffix } = findRareNames(item.name);
        writer.writeUInt8(rarePrefix + 156, 8);
        writer.writeUInt8(rareSuffix + 1 , 8);
        for (let i = 0; i < 3; i++) {
          writer.writeBit(!!mp[i]);
          if (mp[i]) writer.writeUInt16(mp[i] || 0, 11);
          writer.writeBit(!!ms[i]);
          if (ms[i]) writer.writeUInt16(ms[i] || 0, 11);
        }
        break;
    }

    if (runeword) {
      writer.writeUInt16(item.unique?.replace('runeword', '') || 0, 12);
      writer.writeUInt8(0, 4);
    }

    //TODO
    // if (item.personalized) {
    //   const name = item.personalized_name.substring(0, 16);
    //   for (let i = 0; i < name.length; i++) {
    //     if (version > 0x61) {
    //       writer.WriteUInt8(name.charCodeAt(i), 8);
    //     } else {
    //       writer.WriteUInt8(name.charCodeAt(i) & 0x7f, 7);
    //     }
    //   }
    //   writer.WriteUInt8(0x00, version > 0x61 ? 8 : 7);
    // }

    // if (item.type === "tbk") {
    //   writer.WriteUInt8(0, 5);
    // } else if (item.type === "ibk") {
    //   writer.WriteUInt8(1, 5);
    // }

    writer.writeUInt8(item.timestamp || 0, 1);

    const types = itemGetTypes(item.base);
    if (types.has('armo')) {
      writer.writeUInt16(item.defense + 10, 11);
    }
    if (types.has('weap') || types.has('armo')) {
      writer.writeUInt16(item.max_durability, 8);
      if (item.max_durability > 0) {
        writer.writeUInt16(item.current_durability, 9);
      }
    }

    // Write quantity for stackable items (javelins, throwing weapons, etc)
    const baseItem = Data.items[item.base];
    if (baseItem && 'stackable' in baseItem && baseItem.stackable) {
      const quantity = item.quantity || 1;
      writer.writeUInt16(quantity, 9);
    }

    if (item.sockets > 0)
      writer.writeUInt8(item.sockets, 4);

    if (item.quality === Quality.SET) {
      const set_attribute_count = item.stats != null ? item.stats.length : 0;
      //reduced by -1 removed as this seems to be wrong
      const plist_flag = (1 << set_attribute_count) - 1;
      writer.writeUInt8(plist_flag, 5);
    }

    // v105: unknown bit before stats
    if (version >= 105) {
      writer.writeBit(0);
    }

    if (runeword) {
      // Для рунворда пишем статы двумя блоками:
      const runewordData = Data.runes[item.unique];
      const rwStats = {};
      runewordStats(rwStats, runewordData, item.uniqueValues, item);

      // Затем собираем базовые статы (auto, superior, staff)
      const baseStats = {};
      if (item.auto) modsToStats(baseStats, item.auto, item);
      if (item.superior) modsToStats(baseStats, item.superior, item);
      if (item.staff) modsToStats(baseStats, item.staff, item);

      // Пишем базовые статы (или пустой блок если их нет)
      writeItemStats(writer, baseStats);
      // Пишем статы рунворда
      writeItemStats(writer, rwStats);
    } else {
      writeItemStats(writer, item.stats);
    }

    // v105: unknown bit after stats
    if (version >= 105) {
      writer.writeBit(0);
    }
  }//simple

  // v105 simple items: unk=1 bit + 8 data bits before alignment
  if (version >= 105 && item.simple) {
    writer.writeBit(1);
    writer.writeBits(0, 8);
  }

  writer.align();

  if (item.sockets > 0 && item.socketedItems) {
    for (const s of item.socketedItems) {
      const socketItem = allItems[s] ?? {
        base: s,
        simple: true,
        unidentified: false,
        sockets: 0
      };
          
      writer.writeArray(writeItem(
        socketItem,
        { loc: 6, equip: 0, x: 0, y: 0, storage: 0 },
        allItems, version));
    }
  }
  return writer.toArray();
}

function writeItemStats(writer, stats) {
  if (!stats) stats = {};

  const processed = new Set();
  delete stats.poison_count;

  for (const stat of Object.keys(stats)) {
  //for (const stat of Object.keys(stats).sort((a, b) => getStatId(a) - getStatId(b))) {
    if (processed.has(stat)) continue;
    writeStat(writer, stats, stat, processed);
  }

  writer.writeUInt16(0x1ff, 9);
}

// Get stat ID from stat key (handles keys with parameters like "stat#param")
function getStatId(stat) {
  const statName = stat.split('#')[0];
  return Data.itemStatCost[statName]?.id ?? 999;
}

// Encode param and value for special stat types
function getStatParamAndValue(statName, p1, p2, value, stats, statKey) {
  switch (statName) {
    case 'item_skillonattack':
    case 'item_skillonkill':
    case 'item_skillondeath':
    case 'item_skillonhit':
    case 'item_skillonlevelup':
    case 'item_skillongethit': {
      const skillId = Number(p1);
      const level = Number(p2);
      const chance = value;
      return {
        param: (skillId << 6) | (chance & 0x3f),
        value: level
      };
    }
    case 'item_charged_skill': {
      const param1 = Number(p1);
      const param2 = Number(p2);
      const charges = Number(stats[statKey] || 0);
      const maxCharges = Number(stats[statKey] || 0);
      return {
        param: (param1 << 6) | (param2 & 0x3f),
        value: (charges << 8) | (maxCharges & 0xff)
      };
    }
    case 'item_addskill_tab': {
      const tab = Number(p1);
      return {
        param: ((Math.floor(tab / 3)) << 3) | (tab % 3),
        value
      };
    }
    default:
      return {
        param: Number(p1 || 0),
        value
      };
  }
}

// Write a single stat value (base or follow-up)
function writeStatValue(writer, stats, stat, statName, p1, p2, itemStat, isFollowStat) {
  let value = Number(stats[stat] || 0);
  let param = 0;

  if (itemStat.saveparambits) {
    const statParam = !isFollowStat
      ? getStatParamAndValue(statName, p1, p2, value, stats, stat)
      : { param: Number(p1 || 0), value };

    param = statParam.param;
    value = statParam.value;
    writer.writeUInt32(param, itemStat.saveparambits ?? 0);
  }

  if (itemStat.saveadd) value += itemStat.saveadd;
  if (itemStat.savebits) {
    writer.writeUInt32(value, itemStat.savebits ?? 0);
  }
}

// Write stat entry (stat ID + base value + follow-up values)
function writeStat(writer, stats, stat, processed) {
  const [statName, p1, p2] = stat.split('#');
  const itemStat = Data.itemStatCost[statName];
  if (!itemStat) return;

  writer.writeUInt16(itemStat.id, 9);
  processed.add(stat);

  const followCount = followStats[statName] || 0;
  for (let i = 0; i <= followCount; i++) {
    const [statName2, itemStat2] = Object.entries(Data.itemStatCost).find(([, s]) => s.id === itemStat.id + i);;
    const stat2 = i === 0 ? stat : [statName2, p1, p2].filter(Boolean).join('#');
    if (i > 0) processed.add(stat2);

    writeStatValue(writer, stats, stat2, statName, p1, p2, itemStat2, i > 0);
  }
}

function findRareNames(name) {
  if (!name) return {};
  const [pName, sName] = name.split(' ', 2);
  const prefixId = Object.entries(Data.rarePrefix)
    .find(([, v]) => (Locale.strings[v.name] || v.name) === pName)?.[0];
  const suffixId = Object.entries(Data.rareSuffix)
    .find(([, v]) => (Locale.strings[v.name] || v.name) === sName)?.[0];
  return {
    rarePrefix: prefixId != null ? Number(prefixId) : 0,
    rareSuffix: suffixId != null ? Number(suffixId) : 0,
  };
}

function _writeAssignedSkills(skills) {
  const writer = new BitWriter(64);
  writer.length = 64 * 8;
  skills = skills || [];
  for (let i = 0; i < 16; i++) {
    const skillId = _skillId(skills[i]);
    if (skillId > 0) {
      writer.writeUInt32(skillId);
    } else {
      writer.writeUInt32(0xffff);
    }
  }
  return writer.toArray();
}

function _skillId(name) {
  //default to "attack" if empty string or can't find spellname.
  if (name === "") return 0;
  if (!name) return -1;
  const idx = Object.values(Data.skills).findIndex((s) => s && s.skill == name);
  //console.log("name", name, "_skillId:", idx);
  return idx >= 0 ? idx : 0;
}

