function fixHeader(writer) {
  let checksum = 0;
  const eof = Math.ceil(writer.offset / 8);

  // Записываем размер файла по offset 0x08
  writer.seekByte(0x08).writeUInt32(eof);

  // Считаем контрольную сумму
  for (let i = 0; i < eof; i++) {
    let byte = writer.seekByte(i).peekBytes(1)[0];
    if (checksum & 0x80000000) {
      byte += 1;
    }
    checksum = (byte + checksum * 2) >>> 0;
  }

  // Записываем checksum по offset 0x0C
  writer.seekByte(0x0C).writeUInt32(checksum);
}

function writeStatus(status) {
  const arr = new Uint8Array(1);
  arr[0] |= status.hardcore ? 1 << 2 : 0;
  arr[0] |= status.died ? 1 << 3 : 0;
  arr[0] |= status.expansion ? 1 << 5 : 0;
  arr[0] |= status.ladder ? 1 << 6 : 0;
  return arr;
}