const autocolor = value => (value < 0 ? Color.RED : (value > 0 ? Color.BLUE : Color.WHITE));
const colorstat = (value, plus, percent) => colored(
  (plus && value > 0 ? '+' : '') + formatNumber(value || 0, 0, 10000) + (percent ? '%' : ''), autocolor(value));

const dr_chance = (...values) => 100 * (1 - values.reduce((tot, cur) => tot * (1 - 0.01 * cur), 1));
const capped = (value, min, max) => Math.max(min, Math.min(max, value));

function monsterStats(monster) {
  if (!monster) return null;
  let name = monster.name;
  switch (monster.type) {
  case 'champion':
    name = colored(name, Color.BLUE);
    break;
  case 'unique':
  case 'super':
  case 'boss':
    name = colored(name, Color.GOLD);
  // no default
  }
  return {name, ac: monster.base.armorclass, ar: monster.weapon1.display_tohit};
}

