e: 16px;\n      line-height: 1.5;\n\n      p { margin: 1em 0; }\n      i, em { font-style: italic; }\n      b, strong { font-weight: bold; }\n      s, del { text-decoration: line-through; }\n\n      @mixin heading($size, $margin) {\n        font-size: $size;\n        margin: $margin 0;\n        font-weight: bold;\n      }\n      h1 { @include heading(2em, 0.67em); }\n      h2 { @include heading(1.5em, 0.83em); }\n      h3 { @include heading(1.17em, 1em); }\n      h4 { @include heading(1em, 1.33em); }\n      h5 { @include heading(0.83em, 1.67em); }\n      h6 { @include heading(0.67em, 2.33em); }\n\n      .d2md-link { @include link-like; }\n\n      blockquote {\n        margin: 1em 10px;\n        padding: 0.5em 10px;\n        border-left: 5px solid main-color(20%);\n        p:first-child { margin-top: 0; }\n        p:last-child { margin-bottom: 0; }\n      }\n\n      ol, ul {\n        margin: 1em 0;\n        padding-left: 1.8em;\n      }\n      ul { list-style-type: disc; }\n      ol { list-style-type: decimal; }\n\n      hr {\n        margin: 0.5em 0;\n        border-style: inset;\n        border-width: 1px;\n      }\n\n      code {\n        font-family: monospace;\n        padding: .2em .5em;\n        background-color: main-color(5%);\n        border: 1px solid main-color(10%);\n        border-radius: 4px;\n      }\n      pre { margin: 1em 0; }\n      pre code { display: inline-block; }\n\n      table {\n        border-color: #111;\n        box-shadow: 0 0 10px #0a0a0a;\n      }\n      thead, tbody { vertical-align: middle; }\n      thead, tbody, tr, td, th { border-color: inherit; }\n      tr, td, th { vertical-align: inherit; }\n      th { font-weight: bold; }\n      td, th {\n        padding: .5em;\n        border-width: 1px;\n        border-style: solid;\n      }\n      thead {\n        background-image: linear-gradient(to bottom, #242424,#181818);\n        //background-color: main-color(5%);\n      }\n      tbody tr:nth-child(odd) {\n        background-color: #