// Revive

functions[58] = {
  checkTarget(target) {
    return target?.type === 'normal';
  },
  summon(id, stats, level, target) {
    if (target?.type !== 'normal') return;
    const skill = Data.skills[id];
    return {
      revive: true,
      level: stats.level,
  
      skill: id,
      skillLevel: level,
  
      life_percent: skillFormula(skill, 'clc1', stats, level),
      stats: {
        skill: {
          ...skillAuraStats(skill, stats, level),
          ...skillPassiveStats(skill, stats, level),
        },
      },
    };
  },
};

export default functions;
