export function getStoredValue(key, defaultValue, session=false) {
  try {
    const item = (session ? window.sessionStorage : window.localStorage).getItem(key);
    return item != null ? JSON.parse(item) : (typeof defaultValue === "function" ? defaultValue() : defaultValue);
  } catch (error) {
    console.error(error);
    return (typeof defaultValue === "function" ? defaultValue() : defaultValue);
  }
}

// Добавляем функцию с retry механизмом
export async function fetchWithRetry(url, options = {}, retries = 3, delay = 1000) {
  for (let i = 0; i <= retries; i++) {
    try {
      console.log(`Попытка ${i + 1}/${retries + 1}: ${url}`);
      const response = await fetch(url, options);
      
      if (!response.ok) {
        throw new Error(`HTTP error! status: ${response.status}`);
      }
      
      return response;
    } catch (error) {
      console.error(`Ошибка загрузки (попытка ${i + 1}):`, error);
      
      if (i === retries) {
        // Проверяем, можем ли мы загрузить из локального кэша
        const cacheKey = `cache_${url}`;
        const cached = getStoredValue(cacheKey, null);
        if (cached) {
          console.log(`Используем кэшированные данные для ${url}`);
          return new Response(JSON.stringify(cached), {
            status: 200,
            headers: { 'Content-Type': 'application/json' }
          });
        }
        throw new Error(`Не удалось загрузить ${url} после ${retries + 1} попыток: ${error.message}`);
      }
      
      // Ждем перед следующей попыткой
      await new Promise(resolve => setTimeout(resolve, delay * Math.pow(2, i)));
    }
  }
}

// Функция для кэширования ответов
export async function fetchAndCache(url, options = {}) {
  const cacheKey = `cache_${url}`;
  
  try {
    const response = await fetchWithRetry(url, options);
    const data = await response.json();
    
    // Сохраняем в кэш только успешные ответы
    setStoredValue(cacheKey, data);
    return data;
  } catch (error) {
    // Пытаемся загрузить из кэша при ошибке
    const cached = getStoredValue(cacheKey, null);
    if (cached) {
      console.warn(`Используем кэшированные данные для ${url} из-за ошибки:`, error);
      return cached;
    }
    throw error;
  }
}

export function removedStoredValue(key, session=false) {
  try {
    (session ? window.sessionStorage : window.localStorage).removeItem(key);
  } catch (error) {
    console.error(error);
  }
}

export function setStoredValue(key, value, session=false) {
  try {
    (session ? window.sessionStorage : window.localStorage).setItem(key, JSON.stringify(value));
  } catch (error) {
    console.error(error);
  }
}

export function getCookies() {
  const result = [];
  for (const cookie of document.cookie.split(';')) {
    const parts = cookie.split('=');
    if (parts.length === 2) {
      result[parts[0].trim()] = decodeURIComponent(parts[1].trim());
    }
  }
  return result;
}

