import React from 'react';

import Data from '../data';
import Store from '../store';

import { useIconLibrary } from './IconLibrary';
import { socketPositions } from '../graphics';
import { presetItems } from '../logic/itemTypes';
import GameContext from '../gamectx';

function ItemIconLoader({ lib, id, onLoad, index }) {
  Store.useItem(id);
  const image = lib(id);
  React.useEffect(() => {
    let cancelled = false;
    image.then(icon => {
      if (!cancelled) {
        onLoad(index, icon);
      }
    }).catch(error => {
      if (!cancelled) {
        console.error('Error loading item icon:', error);
      }
    });
    return () => {
      cancelled = true;
    };
  }, [image, index, onLoad]);
  return null;
}

export default React.forwardRef(function ItemImage({ id, sockets, ...props }, ref) {
  const item = Store.useItem(id) || presetItems[id];
  const base = item && Data.items[item.base];
  const [icons, setIcons] = React.useState([]);
  const [gemsocket, setSocket] = React.useState();
  const iconLib = useIconLibrary();
  const canvasRef = React.useRef();
  const { gfx, gridSize } = React.useContext(GameContext);

  React.useEffect(() => {
    let cancelled = false;
    gfx.getCommonImage('gemsocket').then(icon => {
      if (canvasRef.current && !cancelled) {
        setSocket(icon);
      }
    }).catch(error => {
      if (!cancelled) {
        console.error('Error loading gemsocket image:', error);
      }
    });
    return () => {
      cancelled = true;
    };
  }, [gfx]);

  const onLoad = React.useCallback((index, icon) => {
    if (!canvasRef.current || !icon) return;
    setIcons(icons => {
      if (icons[index] === icon) return icons;
      icons = icons.slice();
      icons[index] = icon;
      return icons;
    });
  }, []);

  const numSockets = item?.sockets;
  const ethereal = item?.ethereal || item?.stats?.item_ethereal;
  
  React.useEffect(() => {
    if (!canvasRef.current || !base) return;
    
    const image = icons[0];
    if (!image || !image.bitmap || !image.frames || !image.frames.length) return;

    const width = base.invwidth * gridSize;
    const height = base.invheight * gridSize;
    const canvas = canvasRef.current;
    
    // Устанавливаем размеры canvas
    canvas.width = width;
    canvas.height = height;
    
    const ctx = canvas.getContext("2d");
    if (!ctx) return;

    try {
      ctx.clearRect(0, 0, width, height);

      const frame = image.frames[0];
      if (frame && image.bitmap) {
        ctx.globalAlpha = (ethereal ? 0.5 : 1);
        ctx.drawImage(
          image.bitmap, 
          frame.x || 0, frame.y || 0, frame.width || width, frame.height || height, 
          0, 0, frame.width || width, frame.height || height
        );
        ctx.globalAlpha = 1.0;
      }

      if (!numSockets || !base) return;
      
      const pos = socketPositions[`${base.invheight}x${base.invwidth}`]?.[numSockets - 1];
      if (!pos) return;

      const HalfSize = gridSize / 2;
      if (sockets) {
        const sfrm = gemsocket?.frames?.[0];
        if (sfrm && gemsocket?.bitmap) {
          ctx.globalAlpha = 0.25;
          for (let i = 0; i < pos.length; i += 2) {
            ctx.drawImage(
              gemsocket.bitmap, 
              sfrm.x || 0, sfrm.y || 0, sfrm.width || 16, sfrm.height || 16, 
              Math.round(pos[i] * HalfSize) - 1, Math.round(pos[i + 1] * HalfSize) + 1, 
              sfrm.width || 16, sfrm.height || 16
            );
          }
          ctx.globalAlpha = 1.0;
        }
        
        for (let i = 0; i + 1 < icons.length && i < numSockets; ++i) {
          const sockIcon = icons[i + 1];
          if (!sockIcon?.frames?.[0] || !sockIcon.bitmap) continue;
          
          const frm = sockIcon.frames[0];
          ctx.drawImage(
            sockIcon.bitmap, 
            frm.x || 0, frm.y || 0, frm.width || 16, frm.height || 16, 
            Math.round(pos[i * 2] * HalfSize), Math.round(pos[i * 2 + 1] * HalfSize), 
            frm.width || 16, frm.height || 16
          );
        }
      }
    } catch (error) {
      console.error('Error rendering item image:', error);
    }
  }, [iconLib, id, base, numSockets, icons, ethereal, gemsocket, sockets, gridSize]);

  if (!item || !base) {
    return <div {...props} style={{width: gridSize, height: gridSize}} ref={ref}></div>;
  }

  return (
    <div {...props} style={{width: base.invwidth * gridSize, height: base.invheight * gridSize}} ref={ref}>
      <canvas width={base.invwidth * gridSize} height={base.invheight * gridSize} ref={canvasRef}/>
      <ItemIconLoader lib={iconLib} id={id} onLoad={onLoad} index={0}/>
      {item.socketedItems && [...Array(6)].map((_, i) => (
        item.socketedItems[i] ? (
          <ItemIconLoader key={i} lib={iconLib} id={item.socketedItems[i]} onLoad={onLoad} index={i + 1}/>
        ) : null
      ))}
    </div>
  );
});
