import React from 'react';

import Locale from '../../data/locale';
import EditingContext from '../../store/editingContext';
import Store from '../../store';
import Session from '../../store/session';

import { FontAwesomeIcon } from '@fortawesome/react-fontawesome';
import { faFolder, faSpinner } from '@fortawesome/free-solid-svg-icons';
import useApi from '../../api';
import Select, { underlinerFunc } from '../../ui/select';
import { foldersFix } from './Profiles';
import { getProfilePath } from '../../common';
import { exportProfile } from './useLoadProfile';
import { stateSetImported } from '../../logic/stateReducers';

const _L = Locale("ui-import");

function profilesAdd(profiles, data, id, folder) {
  if (!profiles) return profiles;

  data = {
    id: id.toString(),
    value: data.name,
    class: data.class,
    folder,
    date: Math.floor(Date.now() / 1000),
  };

  profiles = profiles.slice();
  const index = profiles.findIndex(profile => parseInt(profile.id) === id);
  if (index >= 0) {
    profiles[index] = data;
  } else {
    profiles.push(data);
  }
  return profiles;
}

const renderFolder = ({id, name, depth}, search) => (
  <span style={{paddingLeft: 8 * depth}}>
    <FontAwesomeIcon icon={faFolder}/> {search ? underlinerFunc(name, search) : name}
  </span>
);

const FolderSelect = React.memo(function FolderSelect({ folder, setFolder }) {
  const loggedIn = Session.useSelector(store => !!store.userName);
  const folders = Session.useSelector(store => store.folders);
  const dispatch = Session.useDispatch();
  const api = useApi();

  const foldersLoaded = React.useRef(false);
  React.useEffect(() => {
    if (foldersLoaded.current) return;
    foldersLoaded.current = true;
    if (!loggedIn || folders) return;
    api.folders().then(
      result => dispatch.setFolders(foldersFix(result)),
      () => null
    );
  }, [api, dispatch, folders, loggedIn]);
  
  const getOptions = React.useCallback(() => {
    if (!folders) return [];
    const children = {};
    for (const id in folders) {
      const parent = folders[id].parent || 0;
      children[parent] = (children[parent] || []);
      children[parent].push(parseInt(id));
    }
    const options = [];
    function traverse(id, depth) {
      options.push({id, name: (id === 0 ? _L`My Profiles` : (folders[id].name || folders[id])), depth});
      if (children[id]) {
        for (const child of children[id]) {
          traverse(child, depth + 1);
        }
      }
    }
    traverse(0, 0);
    return options;
  }, [folders]);

  const onChange = React.useCallback(({id}) => setFolder(id), [setFolder]);

  if (!folders) return null;

  const selected = folders[folder];
  const value = selected ? {id: folder, name: selected.name || selected} : {id: 0, name: _L`My Profiles`};

  return (
    <Select options={getOptions}
            renderOption={renderFolder}
            value={value}
            onChange={onChange}
            className="d2p-save-folder"
    />
  );
});

export default function SaveSection() {
  const [status, setStatus] = EditingContext.useState("saveStatus", null);

  const [saveMode, setSaveMode] = React.useState('all');
  const onChangeSaveMode = React.useCallback(e => setSaveMode(e.target.value), []);

  const [saveName, setSaveName] = React.useState("");
  const onChangeSaveName = React.useCallback(e => setSaveName(e.target.value), []);

  const hasMerc = Store.useProfile(profile => !!profile.merc && Object.values(profile.mercItems).some(Boolean));
  React.useEffect(() => {
    if (!hasMerc && saveMode === 'mercenary') {
      setSaveMode('current');
    }
  }, [hasMerc, saveMode]);

  const [saving, setSaving] = React.useState(false);
  const [folder, setFolder] = React.useState(0);

  const dispatch = Store.useDispatch();
  const mainStore = Store.useStore();
  const api = useApi();

  const sessionDispatch = Session.useDispatch();

  const statusRef = React.useRef();
  const onFocus = React.useCallback(() => {
    statusRef.current.select();
  }, []);

  const userId = Session.useSelector(state => state.userId);
  const onSave = React.useCallback(() => {
    const state = mainStore.getState();
    const data = exportProfile(state, saveName, saveMode);
    const exportedId = (saveMode === 'current' ? state.profiles[state.activeProfile].id : null);
    setSaving(true);
    setStatus(null);
    api.save(data, folder ? {folder} : null, saveName).then(
      id => {
        const url = new URL(getProfilePath(id), window.location);
        setStatus('Ok');
        setTimeout(() => {
          setStatus(null)
        }, 6000)
        sessionDispatch.setProfiles(profiles => profilesAdd(profiles, data, id, folder));
        if (saveMode !== 'mercenary') {
          dispatch.setState(state => stateSetImported(state, id, userId, exportedId, saveName));
        }
      },
      error => setStatus(error.message),
    ).finally(() => setSaving(false));
  }, [saveMode, saveName, mainStore, api, setStatus, dispatch, sessionDispatch, folder, userId]);

  return (
    <div className="d2p-SectionContent d2p-section-save">
      <div className="d2p-description">
        {_L`Enter a name or a short description for your profile. It will show in the page title when the profile is loaded.`}
      </div>
      <div className="d2p-import-options">
        <div className="d2p-save-options">
          <FolderSelect folder={folder} setFolder={setFolder}/>
          <select value={saveMode} onChange={onChangeSaveMode} disabled={saving}>
            <option value='all'>{_L`Save all sets`}</option>
            <option value='current'>{_L`Save current set`}</option>
            {hasMerc && <option value='mercenary'>{_L`Save mercenary`}</option>}
          </select>
        </div>

        <input type="text" className="d2p-save-name" value={saveName} onChange={onChangeSaveName} disabled={saving}/>

        <button onClick={onSave} disabled={saving}>
          {saving && <FontAwesomeIcon icon={faSpinner} spin/>}
          {saving ? _L`Saving` : _L`Save`}
        </button>
      </div>
      {!!status && (
        <div className="d2p-save-status">
          <input type="text" value={status} readOnly ref={statusRef} onFocus={onFocus}/>
        </div>
      )}
    </div>
  );
}
