import Data from '../../data';
import jsep from 'jsep';

const binaryPrecedence = {
  '==': 6, '!=': 6,
  '<': 7,  '>': 7,  '<=': 7,  '>=': 7,
  '+': 9, '-': 9,
  '*': 10, '/': 10,
};
const binaryOps = {
  '==': (a, b) => a === b ? 1 : 0,
  '!=': (a, b) => a !== b ? 1 : 0,
  '<': (a, b) => a < b ? 1 : 0,
  '>': (a, b) => a > b ? 1 : 0,
  '<=': (a, b) => a <= b ? 1 : 0,
  '>=': (a, b) => a >= b ? 1 : 0,
  '+': (a, b) => (a + b) | 0,
  '-': (a, b) => (a - b) | 0,
  '*': (a, b) => (a * b) | 0,
  '/': (a, b) => b ? ((a / b) | 0) : 0,
};
const unaryOps = {
  '-': x => (-x) | 0,
  '+': x => x,
};

jsep.removeAllUnaryOps();
jsep.removeAllBinaryOps();
jsep.removeAllLiterals();
for (const op in binaryOps) {
  jsep.addBinaryOp(op, binaryPrecedence[op]);
}
for (const op in unaryOps) {
  jsep.addUnaryOp(op);
}

function linear(lvl, a, b) {
  return (a + b * (lvl - 1)) | 0;
}
function diminishing(lvl, a, b) {
  return (((110 * lvl) / (lvl + 6) | 0) * (b - a) / 100 | 0) + a;
}

function levelScaling5(lvl, base, s1, s2, s3, s4, s5) {
  if (lvl > 28) return (base + s1 * 7 + s2 * 8 + s3 * 6 + s4 * 6 + s5 * (lvl - 28)) | 0;
  if (lvl > 22) return (base + s1 * 7 + s2 * 8 + s3 * 6 + s4 * (lvl - 22)) | 0;
  if (lvl > 16) return (base + s1 * 7 + s2 * 8 + s3 * (lvl - 16)) | 0;
  if (lvl > 8) return (base + s1 * 7 + s2 * (lvl - 8)) | 0;
  return (base + s1 * (lvl - 1)) | 0;
}

function levelScaling3(lvl, base, s1, s2, s3) {
  if (lvl > 16) return (base + s1 * 7 + s2 * 8 + s3 * (lvl - 16)) | 0;
  if (lvl > 8) return (base + s1 * 7 + s2 * (lvl - 8)) | 0;
  return (base + s1 * (lvl - 1)) | 0;
}

