import { getAssetsPath, PD2 } from "./common";

const baseDir = PD2 ? 'pd2/' : 'lod/';

const loadBuffer = path => {
  const url = getAssetsPath(path);
  //console.log(`Loading buffer from: ${url}`);
  return fetch(url)
    .then(r => {
      if (!r.ok) {
        throw new Error(`Failed to load ${url}: ${r.status} ${r.statusText}`);
      }
      //console.log(`Successfully fetched: ${url}`);
      return r.arrayBuffer();
    })
    .then(b => new Uint8Array(b))
    .catch(error => {
      console.error(`Error loading buffer from ${url}:`, error);
      throw error;
    });
};

const itemLib = fetch(getAssetsPath(baseDir + 'itemlib.json')).then(r => r.json());
const itemarc = [];
export async function itemdc6(name) {
  if (!name) return null;
  const lib = await itemLib;
  const entry = lib[name.toLowerCase()];
  if (!entry) return null;
  const [index, offset, length] = entry;
  if (!itemarc[index]) {
    itemarc[index] = loadBuffer(baseDir + `items${index}.dcx`);
  }
  const buf = await itemarc[index];
  return buf.subarray(offset, offset + length);
}

const paletteAsync = loadBuffer('pal.dat');
const tintsAsync = loadBuffer('tints.dat');

async function myCreateImageBitmap(data) {
  if (window.createImageBitmap) {
    return window.createImageBitmap(data);
  } else {
    const canvas = document.createElement('canvas');
    canvas.width = data.width;
    canvas.height = data.height;
    canvas.getContext('2d').putImageData(data, 0, 0);
    return canvas;
  }
}

export async function makeBitmap(dc6, tint, frameList) {
  if (!dc6 || dc6.length === 0) {
    console.warn('makeBitmap: dc6 data is null or empty');
    return null;
  }

  try {
    const palette = await paletteAsync;
    const tintTable = tint && await tintsAsync;

    if (!palette || palette.length === 0) {
      console.error('makeBitmap: palette not loaded');
      return null;
    }

    const u32 = new Uint32Array(dc6.buffer, dc6.byteOffset, dc6.length >> 2);
    if (u32.length === 0 || u32[0] !== 6) {
      console.warn('makeBitmap: invalid DC6 format');
      return null;
    }
    
    const read32 = pos => {
      if (pos & 3) {
        return dc6[pos] | (dc6[pos + 1] << 8) | (dc6[pos + 2] << 16) | (dc6[pos + 3] << 24);
      } else {
        return u32[pos >> 2];
      }
    };

    const count = u32[4] * u32[5];
    if (!count) {
      console.warn('makeBitmap: no frames found');
      return null;
    }

    if (!frameList) {
      frameList = [...Array(count)].map((_, i) => i);
    } else {
      frameList = frameList.filter(i => i >= 0 && i < count);
    }

    const frames = [];
    let curWidth = 0, curHeight = 0, maxWidth = 0, maxHeight = 0;
    for (const i of frameList) {
      if (i >= u32.length - 6) continue; // Проверка границ
      const offset = u32[6 + i];
      if (offset >= dc6.length - 8) continue; // Проверка границ
      
      const width = read32(offset + 4);
      const height = read32(offset + 8);
      
      if (width <= 0 || height <= 0 || width > 1000 || height > 1000) {
        console.warn(`makeBitmap: invalid frame dimensions ${width}x${height}`);
        continue;
      }
      
      if (curWidth && curWidth + width > 512) {
        maxWidth = Math.max(maxWidth, curWidth);
        curWidth = 0;
        maxHeight += curHeight;
        curHeight = 0;
      }
      frames[i] = {x: curWidth, y: maxHeight, width, height};
      curWidth += width;
      curHeight = Math.max(curHeight, height);
    }
    maxWidth = Math.max(maxWidth, curWidth);
    maxHeight += curHeight;

    if (!maxWidth || !maxHeight) {
      console.warn('makeBitmap: calculated dimensions are zero');
      return null;
    }

    const imageData = new ImageData(maxWidth, maxHeight);
    const data = imageData.data;

    for (const i of frameList) {
      if (!frames[i]) continue;
      
      const offset = u32[6 + i];
      const flip = read32(offset);
      const height = read32(offset + 8);
      let pos = offset + 32;
      const end = read32(offset + 28) + pos;
      
      if (end > dc6.length) {
        console.warn(`makeBitmap: frame ${i} data extends beyond buffer`);
        continue;
      }
      
      let base = (frames[i].x + frames[i].y * maxWidth + (flip ? 0 : maxWidth * (height - 1))) * 4;
      let dst = base;
      
      while (pos < end && pos < dc6.length) {
        let c = dc6[pos++];
        if (c === 0x80) {
          base = dst = base + (flip ? maxWidth : -maxWidth) * 4;
        } else if (c & 0x80) {
          dst += (c & 0x7F) * 4;
        } else {
          while (c-- && pos < dc6.length && dst < data.length - 3) {
            let idx = dc6[pos++];
            if (tint && tintTable && idx < 256 && tint * 256 + idx < tintTable.length) {
              idx = tintTable[tint * 256 + idx];
            }
            if (idx < 256 && idx * 3 + 2 < palette.length) {
              data[dst++] = palette[idx * 3 + 2];
              data[dst++] = palette[idx * 3 + 1];
              data[dst++] = palette[idx * 3];
              data[dst++] = 255;
            } else {
              dst += 4;
            }
          }
        }
      }
    }
    
    return {bitmap: await myCreateImageBitmap(imageData), frames};
  } catch (error) {
    console.error('makeBitmap error:', error);
    return null;
  }
}

export async function createIcon(name, tint) {
  const dc6 = await itemdc6(name);
  return makeBitmap(dc6, tint);
}

const imageCache = {};
export function getCommonImage(name) {
  if (imageCache[name]) return imageCache[name];
  return imageCache[name] = createIcon(name);
}

async function doLoadFont(name) {
  try {
    //console.log(`Loading font: ${name}`);
    const [dc6, tbl] = await Promise.all([
      loadBuffer(`font/${name}.DC6`), 
      loadBuffer(`font/${name}.tbl`)
    ]);

    //console.log(`Font ${name}: DC6 size=${dc6.length}, TBL size=${tbl.length}`);

    const results = await Promise.all([...Array(13)].map((_, i) => makeBitmap(dc6, i ? 9 * 21 + i : null)));
    
    // Check if any makeBitmap calls returned null
    if (results.some(r => r === null)) {
      console.error(`doLoadFont: failed to create bitmaps for font ${name}`);
      return null;
    }
    
    const bitmaps = results.map(r => r.bitmap);
    const frames = results[0].frames;

    const chars = {};
    for (let i = 0; i < 256; ++i) {
      const offset = 12 + i * 14;
      const chr = tbl[offset];
      const width = tbl[offset + 3];
      const height = tbl[offset + 4];
      const frame = tbl[offset + 8];
      chars[chr] = {width, height, frame: frames[frame]};
    }

    //console.log(`Successfully loaded font: ${name}`);
    return {
      render(ctx, x, y, text, color=0) {
        for (let i = 0; i < text.length; ++i) {
          const chr = text.charCodeAt(i);
          if (chr === 0x5C && text.substring(i + 1, i + 5) === 'xffc') {
            i += 5;
            const code = text.charCodeAt(i);
            if (code >= 0x30 && code <= 0x3C) {
              color = code - 0x30;
            }
          } else if (chr === 0xFF && text.substring(i + 1, i + 2) === 'c') {
            i += 2;
            const code = text.charCodeAt(i);
            if (code >= 0x30 && code <= 0x3C) {
              color = code - 0x30;
            }
          } else {
            if (!chars[chr]) continue;
            const {width, height, frame} = chars[chr];
            ctx.drawImage(bitmaps[color], frame.x, frame.y, frame.width, frame.height, x, y - height, frame.width, frame.height);
            x += width;
          }
        }
      },
      measure(text) {
        let result = 0, maxlen = 0;
        for (let i = 0; i < text.length; ++i) {
          const chr = text.charCodeAt(i);
          if (chr === 0x5C && text[i + 1] === 'n') {
            maxlen = Math.max(maxlen, result);
            result = 0;
            i += 1;
          } else if (chr === 0x5C && text.substring(i + 1, i + 5) === 'xffc') {
            i += 5;
          } else if (chr === 0xFF && text.substring(i + 1, i + 2) === 'c') {
            i += 2;
          } else {
            if (!chars[chr]) continue;
            result += chars[chr].width;
          }
        }
        return Math.max(result, maxlen);
      },
    };
  } catch (error) {
    console.error(`doLoadFont: Error loading font ${name}:`, error);
    return null;
  }
}

const fontCache = {};
export function loadFont(name) {
  if (fontCache[name]) return fontCache[name];
  return fontCache[name] = doLoadFont(name);
}

export function clearCache() {
  itemarc.length = 0;
  for (const id in imageCache) {
    delete imageCache[id];
  }
  for (const id in fontCache) {
    delete fontCache[id];
  }
}

