const _L = Locale("ui-equipment");

function HoverNumber({ disabled, value=0, ...props }) {
  const [editing, setEditing] = React.useState(false);
  const [hover, setHover] = React.useState(false);

  const onMouseOver = React.useCallback(() => setHover(true), []);
  const onMouseOut = React.useCallback(() => setHover(false), []);

  const onFocus = React.useCallback(() => setEditing(true), []);
  const onBlur = React.useCallback(() => setEditing(false), []);

  const max = Math.max(Math.abs(props.min), Math.abs(props.max));
  let digits = Math.floor(Math.log10(max)) + 1;
  if (props.digits !== 0) {
    digits += 0.6 + (props.digits || 2);
  }
  const width = 13 * digits + 28;

  const content = (
    <span className={classNames("d2p-HoverNumber", {"d2p-disabled": disabled})} onMouseEnter={onMouseOver} onMouseLeave={onMouseOut}>
      {value}
      {!!(!disabled && (hover || editing)) && <NumberInput value={value} onFocus={onFocus} onBlur={onBlur} style={{width}} {...props}/>}
    </span>
  );

  if (props.min != null && props.max != null && !props.values && !disabled) {
    return (
      <Tooltip tooltip={`${props.min}\u2013${props.max}`} align="left">
        {content}
      </Tooltip>
    );
  }

  return content;
}

const ItemModTip = ({ title, id: curId, group, ranges }) => (
  <div className="d2p-ItemModTip">
    <h3>{title}</h3>
    {group.map(id => {
      const mod = Data.mods[id];
      if (!mod) return null;
      const values = [];
      const modmin = new Map(), modmax = new Map();
      for (let i = 1; i <= 4; ++i) {
        const min = mod[`mod${i}min`], max = mod[`mod${i}max`];
        if (min != null && max != null) {
          const rng = ranges[i - 1];
          if (!rng || rng[0] === rng[rng.length - 1]) {
            values[i - 1] = max;
          } else {
            modmin.set(i, min);
            modmax.set(i, max);
            values[i - 1] = `{${i}}`;
          }
        }
      }
      const stats = modsToStats({}, {[id]: values});
      const lines = statsToLines(stats);
      const text = lines.map(line => {
        const m = line[1].match(/{.*}/);
        if (!m) return null;
        const rng = formatRanges(m[0], modmin, modmax);
        const m2 = rng.match(/^(\+?)\(([^)]*)\)$/);
        if (m2) return m2[1] + m2[2];
        return rng;
      }).filter(Boolean).join(" / ");
      const suffix = Locale.strings[mod.name] || mod.name;
      const ilvlTip = (mod.level ? _L`iLvl ${mod.level}` + ': ' : '');
      return <div key={id} className={classNames("d2p-ModTier", {"d2p-current": id === curId})}>{ilvlTip}{text}{suffix ? ` (${suffix})` : ''}</div>;
    })}
  </div>
);

function ItemModInfo({ id, group, ranges }) {
  let index = group.length - group.indexOf(id);
  let type = "T", title = null;
  if (Data.magicPrefix[id]) {
    type = "P";
    title = _L`Prefix`;
  } else if (Data.magicSuffix[id]) {
    type = "S";
    title = _L`Suffix`;
  } else if (Data.autoMagic[id]) {
    type = "A";
    title = _L`Auto Mod`;
  } else if (Data.crafted[id]) {
    type = "C";
    index = "";
    title = Data.crafted[id].description;
    title = craftingRecipes[title] || title || 'Crafted';
    title = _L(title);
  } else if (Data.qualityItems[id]) {
    type = "Q";
    index = "";
    title = _L`Superior Mod`;
  } else if (Data.staffMods[id]) {
    type = "M";
    index = "";
    title = _L`Staff Mod`;
  } else if (Data.corruptedMods?.[id]) {
    type = "C";
    index = Data.corruptedMods[id].tier || "";
    title = _L`Corrupted Mod`;
  }

  return (
    <Tooltip tooltip={<ItemModTip title={title} id={id} group={group} ranges={ranges}/>} align="left">
      <span className="d2p-label">
        {type}{index}
      </span>
    </Tooltip>
  );
}

const itemModSearch = (opt, search) => opt.name.match(search) || opt.mods?.some(id => {
  const name = Data.mods[id].name;
  return (Locale.strings[name] || name)?.match(search);
});

function ItemModLine({ type, item, onChange, group, id, allGroups, canRemove }) {
  const [expanded, setExpanded] = React.useState(false);

  const ranges = React.useMemo(() => {
    if (!group) return null;
    const ranges = [[], [], [], []];
    for (const mid of group) {
      const mod = Data.mods[mid];
      if (!mod) continue;
      if (mod.mod1min != null && mod.mod1max != null) ranges[0].push([mod.mod1min, mod.mod1max]);
      if (mod.mod2min != null && mod.mod2max != null) ranges[1].push([mod.mod2min, mod.mod2max]);
      if (mod.mod3min != null && mod.mod3max != null) ranges[2].push([mod.mod3min, mod.mod3max]);
      if (mod.mod4min != null && mod.mod4max != null) ranges[3].push([mod.mod4min, mod.mod4max]);
    }

    return ranges.map(rng => {
      rng.sort((a, b) => a[0] - b[0]);
      const res = [];
      for (const [a, b] of rng) {
        if (res.length && a <= res[res.length - 1] + 1) {
          res[res.length - 1] = Math.max(res[res.length - 1], b);
        } else {
          res.push(a, b);
        }
      }
      return res;
    });
  }, [group]);

  const lines = React.useMemo(() => {
    if (!ranges) return null;
    const stats = modsToStats({}, {[id]: ranges.map((rng, i) => {
      if (rng.length && rng[0] === rng[rng.length - 1]) {
        return rng[0];
      } else {
        return `{${i}}`;
      }
    })}, {base: item.base, ilvl: item.ilvl});
    if (Object.keys(stats).length > 2) delete stats.corrupted;
    return statsToLines(stats).map(line => line[1].replace(/\xffc\d/g, ''));
  }, [id, item.ilvl, item.base, ranges]);

  const onSetValue = React.useCallback((index, value) => onChange(item => {
    if (!item[type]?.[id]) return item;
    const values = item[type][id].slice();
    values[index] = value;
    item = {...item};
    item[type] = {...item[type]};

    const newId = findLowestMod(group, values);
    if (newId && newId !== id) {
      const mod = Data.mods[newId];
      for (let i = 0; i < values.length; ++i) {
        if (mod[`mod${i + 1}min`] != null && values[i] < mod[`mod${i + 1}min`]) {
          values[i] = mod[`mod${i + 1}min`];
        }
        if (mod[`mod${i + 1}max`] != null && values[i] > mod[`mod${i + 1}max`]) {
          values[i] = mod[`mod${i + 1}max`];
        }
      }
      delete item[type][id];
      item[type][newId] = values;
      if (mod.level) item.ilvl = Math.max(item.ilvl, mod.level);
    } else {
      item[type][id] = values;
    }
    return item;
  }), [type, id, onChange, group]);

  const value = React.useMemo(() => group ? ({id: group[group.length - 1], name: "name"}) : null, [group]);
  const getOptions = React.useCallback(() => {
    const options = [];
    const makeList = groups => groups.map(g => {
      let reason = null;
      if (!g.mods.includes(id)) {
        //TODO: localization
        if (Object.keys(item[type]).some(m => m !== id && Data.mods[m].group === g.group)) {
          reason = _L`Mod of this type already present on the item`;
        } else if (type === 'staff' && Data.staffMods[g.mods[0]]) {
          const tier = Data.staffMods[g.mods[0]].tier;
          if (Object.keys(item.staff).some(m => m !== id && Data.staffMods[m] && Math.abs(Data.staffMods[m].tier - tier) > 18)) {
            reason = _L`Staff mods cannot be more than 3 tiers apart`;
          }
        } else if (g.type === "prefix" || g.type === "suffix") {
          const count = itemCountMods(item, id);
          const limit = (item.quality === Quality.MAGIC ? 1 : 3);
          if (count[g.type] >= limit) {
            reason = (g.type === "prefix" ? _L`No space for more prefixes` : _L`No space for more suffixes`);
          }
        }
        if (!reason && Data.mods[g.mods[0]]?.sockets) {
          if (item.unique) {
            const unique = Data.uniqueItems[item.unique] || Data.setItems[item.unique];
            if (unique && unique.sockets) {
              reason = _L`Cannot have multiple socket mods`;
            }
          }
          for (const mods of [item.corrupted, item.crafted, item.superior, item.mods, item.auto, item.staff]) {
            if (mods && Object.keys(mods).some(m => Data.mods[m]?.sockets)) {
              reason = _L`Cannot have multiple socket mods`;
              break;
            }
          }
        }
      }
      return {
        id: g.mods[g.mods.length - 1],
        mods: g.mods,
        name: g.name,
        disabled: !!reason,
        reason,
      };
    });
    //TODO: localization
    if (allGroups.corrupted) options.push(...makeList(allGroups.corrupted)); 
    if (allGroups.crafted) options.push(...makeList(allGroups.crafted)); 
    if (allGroups.superior) options.push(...makeList(allGroups.superior)); 
    if (allGroups.prefix) options.push({title: "Prefixes", options: makeList(allGroups.prefix)});
    if (allGroups.suffix) options.push({title: "Suffixes", options: makeList(allGroups.suffix)});
    if (allGroups.auto) options.push(...makeList(allGroups.auto));
    if (allGroups.staff) options.push(...makeList(allGroups.staff));
    return options;
  }, [type, item, id, allGroups]);

  const isExpandable = React.useMemo(() => {
    const options = getOptions();
    const count = options.reduce((prev, cur) => prev + (cur.options ? cur.options.length : 1), 0);
    return count > 0 && (!id || count > 1);
  }, [getOptions, id]);

  const onClick = React.useCallback(e => {
    if (!expanded && isExpandable && !e.target.closest(".d2p-HoverNumber")) {
      setExpanded(true);
    }
  }, [expanded, isExpandable]);

  const used = [];
  const contents = id ? (
    <div className={classNames("d2p-mod-contents", {"d2p-expandable": isExpandable})} onClick={onClick}>
      {lines.map((line, i) => (
        <div key={i}>
          {replaceReact(line, /{(\d)(?:;(\w+))?}/g, (m, index, func) => {
            index = parseInt(index);
            switch (func) {
            case 'poison':
              if (used[index]) {
                return Math.round(item[type][id][index] * (item.stats.poisonlength || 0) / 256);
              } else {
                const factor = (item.stats.poisonlength || 0) / 256;
                const rng = ranges[index].map(x => Math.round(x * factor));
                return <HoverNumber digits={0} value={Math.round(item[type][id][index] * factor)} onChange={value => onSetValue(index, Math.round(value / factor))}
                  values={rng} min={rng[0]} max={rng[rng.length - 1]} disabled={expanded}/>;
              }
            case 'per128':
              if (used[index]) {
                return (item[type][id][index] * 100 / 128) | 0;
              } else {
                const rng = ranges[index].map(x => (x * 100 / 128) | 0);
                return <HoverNumber digits={0} value={(item[type][id][index] * 100 / 128) | 0} onChange={value => onSetValue(index, Math.ceil(value * 128 / 100))}
                  values={rng} min={rng[0]} max={rng[rng.length - 1]} disabled={expanded}/>;
              }
            default:
              if (used[index]) {
                return item[type][id][index];
              } else {
                const rng = ranges[index];
                return <HoverNumber digits={0} value={item[type][id][index]} onChange={value => onSetValue(index, value)} values={rng} min={rng[0]} max={rng[rng.length - 1]} disabled={expanded}/>;
              }
            }
          })}
        </div>
      ))}
      {!expanded && (
        <div className="d2p-mods-info">
          <ItemModInfo id={id} group={group} ranges={ranges}/>
          {!!isExpandable && <FontAwesomeIcon icon={faChevronDown} className="d2p-arrow"/>}
        </div>
      )}
    </div>
  ) : (
    <div className="d2p-mod-contents d2p-expandable" onClick={onClick}>
      <div>Add Mod</div>
    </div>
  );

  const renderOption = React.useCallback((opt, search) => {
    const option = <span>{search ? underlinerFunc(opt.name, search) : opt.name}</span>
    if (opt.disabled) {
      return (
        <Tooltip tooltip={opt.reason} align="left">
          {option}
        </Tooltip>
      );
    } else {
      return option;
    }
  }, []);

  const onSelect = React.useCallback(({id: newId}) => onChange(item => {
    const mod = Data.mods[newId];
    if (!mod || (group && group.includes(newId))) return item;
    item = {...item};
    item[type] = {...item[type]};
    if (id) delete item[type][id];
    const values = [];
    if (mod.mod1max != null) values[0] = mod.mod1max;
    if (mod.mod2max != null) values[1] = mod.mod2max;
    if (mod.mod3max != null) values[2] = mod.mod3max;
    if (mod.mod4max != null) values[3] = mod.mod4max;
    item[type][newId] = values;
    if (mod.level) item.ilvl = Math.max(item.ilvl, mod.level);
    return item;
  }), [type, onChange, id, group]);

  const selectRef = React.useRef();
  React.useEffect(() => {
    if (expanded && selectRef.current) {
      selectRef.current.focus();
    }
  }, [expanded]);

  const onClose = React.useCallback(() => setExpanded(false), []);

  const onRemove = React.useCallback(() => onChange(item => {
    item = {...item};
    item[type] = {...item[type]};
    delete item[type][id];
    return item;
  }), [type, id, onChange]);

  //TODO: localization
  return (
    <li className={id ? null : "d2p-empty"}>
      {!!(canRemove && id) && (
        <span className="d2p-mod-remove" title={`Remove Stat`} onClick={onRemove}>
          <FontAwesomeIcon icon={faTimes}/>
        </span>
      )}
      {expanded ? (
        <Select options={getOptions}
                renderValue={() => contents}
                placeholder={contents}
                renderOption={renderOption}
                value={value}
                onChange={onSelect}
                searchLimit={10}
                searchFunc={itemModSearch}
                searchMiddle={true}
                className="d2p-ModSelect"
                ref={selectRef}
                onClose={onClose}
                />
      ) : contents}
    </li>
  );
}

function BasicItemSection({ item, onChange, type, modGroups, children, canRemove }) {
  if (!modGroups[type]) return null;

  const id = Object.keys(item[type])[0];
  const group = id && findModGroup(modGroups, id);

  return (
    <div className="d2p-ItemMods">
      {children}
      <ul className="d2p-ItemModList">
        <ItemModLine type={type} item={item} onChange={onChange} group={group?.mods} id={id} allGroups={modGroups} canRemove={canRemove}/>
      </ul>
    </div>
  );
}

