function GenericUniqueSection({ item, onChange, children }) {
  const unique = (Data.uniqueItems[item.unique] || Data.setItems[item.unique] || Data.runes[item.unique]);
  const isRuneword = (item.quality === Quality.RUNEWORD);

  const ranges = React.useMemo(() => {
    if (!unique) return null;
    const ranges = [];
    if (isRuneword) {
      for (let i = 1; i <= 7; ++i) {
        if (unique[`t1code${i}`]) {
          if (unique[`t1min${i}`] >= unique[`t1max${i}`]) {
            ranges[i - 1] = unique[`t1max${i}`];
          } else {
            ranges[i - 1] = [unique[`t1min${i}`], unique[`t1max${i}`]];
          }
        }
      }
    } else {
      for (let i = 1; i <= 12; ++i) {
        if (unique[`prop${i}`]) {
          if (unique[`min${i}`] >= unique[`max${i}`]) {
            ranges[i - 1] = unique[`max${i}`];
          } else {
            ranges[i - 1] = [unique[`min${i}`], unique[`max${i}`]];
          }
        }
      }
    }
    return ranges;
  }, [unique, isRuneword]);

  const lines = React.useMemo(() => {
    if (!ranges) return null;
    const values = ranges.map((rng, i) => Array.isArray(rng) ? `{${i}}` : rng);
    const stats = (isRuneword ? runewordStats : uniqueStats)({}, unique, values, {base: item.base, ilvl: item.ilvl});    
    return statsToLines(stats).map(line => line[1]);
  }, [ranges, unique, item.ilvl, item.base, isRuneword]);

  const onSetValue = React.useCallback((index, value) => onChange(item => {
    if (ranges[index] && Array.isArray(ranges[index])) {
      value = Math.max(value, ranges[index][0]);
      value = Math.min(value, ranges[index][1]);
    }
    const values = item.uniqueValues.slice();
    values[index] = value;
    return {...item, uniqueValues: values};
  }), [ranges, onChange]);

  const used = [];
  return (
    <div className="d2p-ItemMods">
      {children}
      <ul className="d2p-ItemModList">
        <li>
          <div className="d2p-mod-contents">
            {lines.map((line, i) => (
              <div key={i}>
                {replaceReact(line, /{(\d)(?:;(\w+))?}/g, (m, index, func) => {
                  index = parseInt(index);
                  const rng = ranges[index];
                  switch (func) {
                  case 'skill':
                    return (
                      <select value={item.uniqueValues[index]} onChange={e => onSetValue(index, parseInt(e.target.value))}>
                        {[...Array(rng[1] - rng[0] + 1)].map((_, x) => x + rng[0]).map(value => {
                          const skill = Data.skills[value];
                          const skilldesc = skill && Data.skillDesc[skill.skilldesc];
                          if (!skilldesc) return null;
                          return [Locale.strings[skilldesc.strname], <option key={value} value={value}>{Locale.strings[skilldesc.strname]}</option>];
                        }).sort((a, b) => a[0].localeCompare(b[0])).map(a => a[1])}
                      </select>
                    );
                  case 'skillclass':
                    const skill = Data.skills[item.uniqueValues[index]];
                    if (!skill.charclass) return '';
                    return Locale.istrings[Data.strClassOnly[Data.classes.indexOf(skill.charclass)]];
                  case 'classskills':
                    return (
                      <select value={item.uniqueValues[index]} onChange={e => onSetValue(index, parseInt(e.target.value))}>
                        {[...Array(rng[1] - rng[0] + 1)].map((_, x) => x + rng[0]).map(value => (
                          <option key={value} value={value}>{Data.info.legacyFormat ? Locale.istrings[Data.strClassSkillsStat[value]] : formatStr(Locale.istrings[Data.strClassSkillsStat[value]], 3)}</option>
                        ))}
                      </select>
                    );
                  case 'lvl':
                    return (
                      <React.Fragment>
                        <HoverNumber digits={2} value={item.uniqueValues[index] / 8} onChange={value => onSetValue(index, Math.round(value * 8))} min={rng[0] / 8} max={rng[1] / 8} step={0.125}/>/lvl
                      </React.Fragment>
                    );
                  default:
                    if (used[index]) {
                      return item.uniqueValues[index];
                    } else {
                      return <HoverNumber digits={0} value={item.uniqueValues[index]} onChange={value => onSetValue(index, value)} min={rng[0]} max={rng[1]}/>;
                    }
                  }
                })}
              </div>
            ))}
          </div>
        </li>
      </ul>
    </div>
  );
}

