export function isSubTypeEx(type, ...types) {
  if (types.includes(type)) return true;
  const info = Data.itemTypes[type];
  return info && ((info.equiv1 && isSubTypeEx(info.equiv1, ...types)) || (info.equiv2 && isSubTypeEx(info.equiv2, ...types)));
}

export function isSubType(type, what) {
  if (type === what) return true;
  const info = Data.itemTypes[type];
  return info && ((info.equiv1 && isSubType(info.equiv1, what)) || (info.equiv2 && isSubType(info.equiv2, what)));
}

export function isEquippedIn(type, loc) {
  const info = Data.itemTypes[type];
  return info && (info.bodyloc1 === loc || info.bodyloc2 === loc);
}

