import React from 'react';
import ReactDOM from 'react-dom/client';

import './reset.scss';
import './images.css';

import App from './App';

import { mapStackTrace } from 'sourcemapped-stacktrace';

import loadData from './data/load';
import Store from './store';
import Session from './store/session';
import EditingContext from './store/editingContext';

import { getProfilePath, getStoredValue, setStoredValue, PD2, PTR } from './common';
import { stateFix } from './logic/stateReducers';
import { Api } from './api';
import { exportProfile } from './components/import/useLoadProfile';

const mapStackTraceP = stack => new Promise(resolve => {
  mapStackTrace(stack, result => resolve(result));
});

// Global error handler to catch errors that React Error Boundary doesn't catch
let globalErrorReporter = null;

window.addEventListener('error', (event) => {
  console.error('Global error caught:', event.error);
  if (globalErrorReporter && event.error) {
    globalErrorReporter.handleGlobalError(event.error);
  }
});

window.addEventListener('unhandledrejection', (event) => {
  console.error('Unhandled promise rejection:', event.reason);
  if (globalErrorReporter && event.reason) {
    const error = event.reason instanceof Error ? event.reason : new Error(event.reason.toString());
    globalErrorReporter.handleGlobalError(error);
  }
});

class ErrorReporter extends React.Component {
  constructor(props) {
    super(props);
    this.state = {};
    
    // Register this component as the global error reporter
    globalErrorReporter = this;
  }
  
  componentWillUnmount() {
    // Cleanup global error reporter reference
    if (globalErrorReporter === this) {
      globalErrorReporter = null;
    }
  }
  
  handleGlobalError = (error) => {
    if (!this.state.error) {
      this.setState({
        error: {
          message: error.message || 'Unknown error',
          stack: error.stack || 'No stack trace available',
          isGlobalError: true
        }
      });
      
      // Map stack trace for global errors too
      if (error.stack && !this.mapped) {
        this.mapped = true;
        mapStackTraceP(error.stack).then(stack => {
          this.setState(state => ({
            error: {
              ...state.error,
              stack: stack.join('\n')
            }
          }));
        });
      }
    }
  }

  static getDerivedStateFromError(error) {
    if (!ErrorReporter.caught) {
      ErrorReporter.caught = true;
      return {error: {message: error.message, stack: error.stack}};
    }
  }

  componentDidCatch(error, info) {
    if (!this.mapped) {
      this.mapped = true;
      Promise.all([mapStackTraceP(error.stack), mapStackTraceP(info.componentStack)]).then(([stack, components]) => this.setState(state => ({error: {
        ...state.error,
        stack: stack.join('\n'),
        components: components.join('\n'),
      }})));
    }
  }

  onSave = () => {
    const state = Store.instance.getState();
    const api = new Api();
    this.setState({saved: {saving: true}});
    api.save(exportProfile(state, 'Error report'), {error: true}).then(
      id => this.setState({saved: {id}}),
      error => this.setState({saved: {error: error.message}}),
    );
  }

  render() {
    if (this.state.error) {
      const {saved, error: {message, stack, components, isGlobalError}} = this.state;

      return (
        <div className="d2p-ErrorReport">
          <div>
            <h3>🚨 Error Detected</h3>
            <div style={{background: '#2c1810', color: '#ff6b6b', padding: '15px', marginBottom: '20px', borderRadius: '5px', border: '2px solid #ff6b6b'}}>
              <h4>Error Message:</h4>
              <pre style={{whiteSpace: 'pre-wrap', fontFamily: 'monospace', fontSize: '14px'}}>
                {message || 'Unknown error'}
              </pre>
              {isGlobalError && (
                <p style={{color: '#ffa500', marginTop: '10px'}}>
                  ⚠️ This is a global error that was caught outside React components.
                </p>
              )}
            </div>
            
            <p>Please submit a report over at <a href="https://discord.gg/" target="_blank" rel="noopener noreferrer">Discord</a> describing
            what you were doing, along with the information below.</p>
            <p>If you believe the profile is relevant, please include a link to it as well.</p>
            <p>
              {!saved && <span className="d2p-save" onClick={this.onSave}>Save profile</span>}
              {!!(saved && saved.saving) && <span>Saving...</span>}
              {!!(saved && saved.id) && <a href={getProfilePath(saved.id)} target="_blank" rel="noopener noreferrer">{new URL(getProfilePath(saved.id), window.location.href).href}</a>}
              {!!(saved && saved.error) && <span className="d2p-error">{saved.error}</span>}
            </p>
            
            <details style={{marginTop: '20px'}}>
              <summary style={{cursor: 'pointer', color: '#d4af37'}}>🔍 Technical Details (click to expand)</summary>
              <div className="d2p-report" style={{marginTop: '10px', background: '#1a1a1a', color: '#ccc', padding: '15px', borderRadius: '5px', fontSize: '12px', fontFamily: 'monospace', whiteSpace: 'pre-wrap'}}>
                Error Type: {isGlobalError ? 'Global Error' : 'React Component Error'}{'\n'}
                Message: {message || 'Unknown error'}{'\n'}
                {'\n'}
                {!!stack && 'Stack Trace:\n' + stack + '\n\n'}
                {!!components && 'React Components:\n' + components + '\n\n'}
                User Agent: {navigator.userAgent}{'\n'}
                URL: {window.location.href}{'\n'}
                Timestamp: {new Date().toISOString()}
              </div>
            </details>
          </div>
        </div>
      );
    }

    return this.props.children;
  }
}

(async function() {
  const editingContext = new EditingContext();

  // Clear any corrupted storage that might be causing issues
  try {
    // Check if localStorage has any corrupted entries
    const testKeys = ['d2p-gameVersion', 'cache_/assets/game/data.json', 'cache_/assets/game/strings.json'];
    for (const key of testKeys) {
      const value = localStorage.getItem(key);
      if (value && value.includes('<!DOCTYPE')) {
        console.warn(`Clearing corrupted localStorage entry: ${key}`);
        localStorage.removeItem(key);
      }
    }
  } catch (e) {
    console.warn('Error checking localStorage:', e);
  }
  
  // Ensure we have a valid game version
  let gameVersion = getStoredValue('d2p-gameVersion', 'blizzless');

  // Validate the game version and fallback to blizzless if invalid
  const validVersions = ['d2r', 'lod', 'ptr', 'pd2', 'blizzless'];
  if (!validVersions.includes(gameVersion)) {
    console.warn(`Invalid game version '${gameVersion}', falling back to 'blizzless'`);
    gameVersion = 'blizzless';
    setStoredValue('d2p-gameVersion', gameVersion);
  }
  
  // For lod version, check if the folder exists, if not use d2r
  if (gameVersion === 'lod') {
    console.log('LoD version selected, but using root assets folder since no lod/ subdirectory exists');
  }
  
  console.log(`Starting data load with game version: ${gameVersion}`);
  console.log(`PD2: ${PD2}, PTR: ${PTR}`);
  
  const dataVersion = PD2 ? 'pd2' : (PTR ? 'ptr' : gameVersion);
  console.log(`Data version to load: ${dataVersion}`);

  const dataLoaded = loadData(dataVersion);

  let loading = null;
  const match = window.location.pathname.match(/\/d2planner(?:-pd2|-ptr)?\/(\w{8,9})$/);
  if (match) {
    const setName = window.location.hash && decodeURIComponent(window.location.hash.substring(1));
    loading = (new Api().load(match[1])).then(
      async result => {
        await dataLoaded;
        result = stateFix(result, match[1], result.user);
        if (setName) {
          if (!isNaN(setName)) {
            const index = parseInt(setName) - 1;
            if (index >= 0 && index < result.profiles.length) {
              result.activeProfile = index;
            }
          } else {
            const index = result.profiles.findIndex(profile => profile.name === setName);
            if (index >= 0) {
              result.activeProfile = index;
            }
          }
        }
        await Store.instance.setState(result);
        const profile = result.profiles[result.activeProfile];
        if (profile.buildinfo?.text) {
          editingContext.dispatch({type: "buildinfo"});
        }
      },
      error => error.message,
    );
  }

  await dataLoaded;

  // uncomment this if you want to wait for profile load before rendering the page
  if (loading) await loading;

  const session = new Session();
  const api = new Api(session.store);
  api.updateLogin();

  //history.subscribe(state => state, state => console.log(state));

  ReactDOM.createRoot(document.getElementById('root'))
  .render(
    <ErrorReporter>
      <App session={session} loading={loading} editingContext={editingContext}/>
    </ErrorReporter>,
    document.querySelector('.d2planner-wrapper')
  );
})();
