const _L = Locale("title");

const tabComponents = {
  buildinfo: BuildInfo,
  equipment: EquipmentPane,
  character: CharacterPane,
  calculator: CalculatorPane,
  import: ImportPane,
};

function NewConfirmation({ onResolve, onClose }) {
  return (
    <Dialog title={_L`New profile`} modal onClose={onClose}>
      <Dialog.Content>
        <p>{_L`Delete all sets and start from a blank profile?`}</p>
      </Dialog.Content>
      <Dialog.Footer>
        <button onClick={() => onResolve(true)}>{_L`Yes`}</button>
        <button onClick={() => onResolve(false)}>{_L`No`}</button>
      </Dialog.Footer>
    </Dialog>
  );
}

function ProfileNewButton() {
  const isEmpty = Store.useSelector(state => stateIsEmpty(state));
  const imported = Store.useSelector(state => state.imported);
  const dispatch = Store.useDispatch();
  const overlays = React.useContext(OverlayContext);
  const onClick = React.useCallback(async () => {
    if (imported !== true && !await overlays.async(<NewConfirmation/>)) return;
    dispatch.setState(stateFix());
  }, [dispatch, overlays, imported]);
  if (isEmpty) return null;
  return (
    <Tooltip tooltip={_L`New profile`}>
      <FontAwesomeIcon icon={faFile} onClick={onClick}/>
    </Tooltip>
  );
}

