            {HasPTR && <label><input type="radio" checked={gameVersion === 'ptr'} onChange={() => onSetVersion('ptr')}/> PTR</label>}
            {/* <label><input type="radio" checked={gameVersion === 'pd2'} onChange={() => onSetVersion('pd2')}/> PD2</label> */}
