const App = React.memo(function App({ loading }) {
  const overlays = React.useContext(OverlayContext);
  const [spinner, setSpinner] = EditingContext.useState("spinner", 0);

  const [gameVersion, setGameVersion] = React.useState(() => PD2 ? "pd2" : (PTR ? "ptr" :(getStoredValue("d2p-gameVersion", "blizzless"))));
  const onSetVersion = React.useCallback(newVersion => {
    if (newVersion === gameVersion || !GameVersions[newVersion]) return;
    if (GameVersions[gameVersion]) {
      const oldGfx = GameVersions[gameVersion].gfx;
      const newGfx = GameVersions[newVersion].gfx;
      if (oldGfx !== newGfx) {
        oldGfx?.clearCache();
        newGfx?.clearCache();
      }
    }
    if (!GameVersions[newVersion].suffix) setStoredValue("d2p-gameVersion", newVersion);
    setGameVersion(newVersion);
    if (true/*GameVersions[newVersion].suffix || GameVersions[gameVersion].suffix*/) {
      window.location.pathname = window.location.pathname.replace(/d2planner(-\w+)?/, GameVersions[newVersion].suffix ? `d2planner-${newVersion}` : 'd2planner');
    }
  }, [gameVersion]);

  const [tab, setTab] = React.useState("equipment");

  const userLevel = Session.useSelector(store => store.userLevel || 0);
  const hasBuildInfo = Store.useProfile(profile => !!profile.buildinfo?.text);
  const showBuildInfo = (userLevel >= BuildInfoLevel || hasBuildInfo);

  const title = Store.useSelector(state => state.name);
  React.useEffect(() => {
    const _Lt = Locale("title");
    const pageTitle = _Lt`Diablo II Character Planner`;
    if (title) {
      document.title = title + " - " + pageTitle;
    } else {
      document.title = pageTitle;
    }
  }, [title]);

  const fireOnce = React.useRef(false);
  React.useEffect(() => {
    if (fireOnce.current) return;
    fireOnce.current = true;
    let cancelled = false;
    if (loading) {
      setSpinner(spin => spin + 1);
      loading.then(error => {
        if (!cancelled && error) {
          overlays.async(<ErrorPopup message={error}/>);
        }
      }).finally(() => {
        if (!cancelled) {
          setSpinner(spin => spin - 1);
        }
      });
    }
    return () => {
      cancelled = true;
    };
  }, [loading, setSpinner, overlays]);

  const tabList = React.useMemo(() => {
    const tabs = [
      { id: "buildinfo", name: _L`Guide` },
      { id: "equipment", name: _L`Equipment` },
      { id: "character", name: _L`Character` },
      { id: "calculator", name: _L`Calculations` },
      { id: "import", name: _L`Save/Load` },
    ];
    if (!showBuildInfo) {
      tabs.splice(0, 1);
    }
    return tabs;
  }, [showBuildInfo]);

  const editingCallback = React.useCallback(({ type }) => {
    switch (type) {
    case "buildinfo":
      if (showBuildInfo) {
        setTab("buildinfo");
        return true;
      }
      break;
    case "item":
    case "slot":
      setTab("equipment");
      break;
    case "equipment":
      setTab("equipment");
      return true;
    // no default
    }
  }, [showBuildInfo]);
  EditingContext.useHandler(editingCallback);

  React.useLayoutEffect(() => {
    if (!showBuildInfo && tab === "buildinfo") {
      setTab("equipment");
    }
  }, [tab, showBuildInfo]);

  const dispatch = Store.useDispatch();
  const [{ isDropping }, dropRef] = useDrop(() => ({
    accept: [NativeTypes.FILE],
    drop(item) {
      const file = item.files?.[0];
      if (file?.name.match(/\.d2s$/i)) {
        parseFile(file).then(
          result => dispatch.setState(state => stateAddProfile(state, result.profile, result.items)),
          error => overlays.async(<ErrorPopup title={_L`Failed to parse file`} message={error.message}/>)
        );
      }
    },
    collect: monitor => ({ isDropping: monitor.isOver() && monitor.canDrop() }),
  }), [dispatch]);

  const TabComponent = tabList.find(t => t.id === tab) ? tabComponents[tab] : null;

  const gameCtx = GameVersions[gameVersion] || GameVersions.d2r;

  return (
    <GameContext.Provider value={gameCtx}>
      <IconLibrary>
        <div className={classNames("d2planner-App", {"d2p-dropping": isDropping, "d2p-game-hd": gameCtx.gfx.hd})} ref={dropRef}>
          <Header gameVersion={gameVersion} onSetVersion={onSetVersion}/>
          <div className="d2p-Body">
            <div className="d2p-LeftColumn">
              <Paperdoll/>
              <div style={{flex: '0 0 10px'}}/>
              <ProfileList/>
            </div>
            <Tabs tabs={tabList} value={tab} onChange={setTab} className="d2p-MainColumn">
              {!!TabComponent && <TabComponent/>}
            </Tabs>
            <div className="d2p-RightColumn">
              <Stats/>
            </div>
          </div>
          <DragLayer/>
          {spinner > 0 && (
            <Overlay>
              <div className="d2p-Spinner"/>
            </Overlay>
          )}
        </div>
      </IconLibrary>
    </GameContext.Provider>
  );
});

export default function AppContext({ session, loading, editingContext }) {
  return (
    <React.Fragment>
      {/* <AdUnit id="d2planner-left" className="d2planner-ad-left"/> */}
      <DndProviderWrapper>
        <Store.Provider store={Store.instance}>
          <Session.Provider store={session}>
            <EditingContext.Provider context={editingContext}>
              <ModifierContext>
                <OverlayRoot>
                  <ImportTracker>
                    <App loading={loading}/>
                  </ImportTracker>
                </OverlayRoot>
              </ModifierContext>
            </EditingContext.Provider>
          </Session.Provider>
        </Store.Provider>
      </DndProviderWrapper>
      {/* <AdUnit id="d2planner-right" className="d2planner-ad-right"/> */}
    </React.Fragment>
  );
}
