import React from 'react';
import Session from './store/session';

import jwtDecode from 'jwt-decode';

import md5 from 'md5';
import Locale from './data/locale';
import { getApiPath, getStaticApiPath, getStoredValue, removedStoredValue, setStoredValue } from './common';
import {writeCharacter} from './logic/binary/write2ds';

const tokenVar = 'd2p-token';

function passwordHash(password) {
  return md5('SmartSalt' + password, {encoding: 'binary'});
}

export class Api {
  constructor(store) {
    this.store = store;
  }

  updateLogin() {
    // const token = getStoredValue(tokenVar, () => getStoredValue(tokenVar), true);
    // const data = token && jwtDecode(token);
    // if (data?.userName) {
    //   this.store.dispatch.setUser(data.userId, data.userName, data.userLevel || 1);
    // } else {
    //   this.store.dispatch.setUser(0, '', 0);
    // }
  }

  authHeaders() {
    const token = getStoredValue(tokenVar, () => getStoredValue(tokenVar), true);
    if (token) {
      return {
        'Authorization': `Bearer ${token}`,
      };
    }
  }

  async fetchAuth(url, options) {
    const response = await fetch(url, {
      ...options,
      headers: this.authHeaders(),
    }).catch(() => null);
    if (response && response.status >= 400 && response.status <= 499) {
      removedStoredValue(tokenVar);
      removedStoredValue(tokenVar, true);
      if (this.store) {
        this.store.dispatch.setUser(0, '', 0);
      }
      return false;
    }
    if (!response?.ok) {
      return null;
    }
    return await response.json().catch(() => null);
  }

  async account(action, params) {
    if (action === 'signout') {
      removedStoredValue(tokenVar);
      removedStoredValue(tokenVar, true);
      if (this.store) {
        this.store.dispatch.setUser(0, '', 0);
      }
      return;
    }

    const data = new FormData();
    data.set('action', action);

    if (params) {
      if (params.name != null) data.set('user_name', params.name);
      if (params.email) data.set('user_email', params.email);
      if (params.reset_code != null) data.set('reset_code', params.reset_code);
      if (params.password != null && (params.password || action !== "options")) data.set('password_hash', passwordHash(params.password));
      if (params.password_old != null) data.set('password_old_hash', passwordHash(params.password_old));
      //if (params.remember) data.set('user_remember', 'true');
      if (params.password_old != null) data.set('user_name', this.store.getState().userName || "");
    }

    const result = await this.fetchAuth(getApiPath('account'), {
      method: 'POST',
      body: data,
    });

    if (result?.token) {
      setStoredValue(tokenVar, result.token, !params?.remember);
      this.updateLogin();
    } else if (!result || result.error || result.errors) {
      const _L = Locale("account");
      throw Error(result?.errors?.[0] || result?.error || _L`Unknown error.`);
    }

    return true;
  }

  async save(data, params, title) {
    const id = Date.now().toString();
    const blob = new Blob(
      [JSON.stringify({ id, data, params }, null, 2)],
      { type: "application/json" }
    );
    const url = URL.createObjectURL(blob);
    const a = document.createElement("a");
    a.href = url;
    const filename = (title?.trim() || `profile-${id}`) + ".json";
    a.download = filename;
    a.click();
    URL.revokeObjectURL(url);
  }

  async saved2s(state, data, params, title) {
    const id = Date.now().toString();
    let gameVersion = getStoredValue('d2p-gameVersion', 'd2r');
    const blob = new Blob(
      [writeCharacter(state, data.profiles[state.activeProfile], data.items, title, 
        gameVersion === 'd2r' ? 105 :
        gameVersion === 'blizzless' ? 99 : 
        gameVersion === 'lod' ? 96 : 
        null)],
      { type: "application/octet-stream" }
    );
    const url = URL.createObjectURL(blob);
    const a = document.createElement("a");
    a.href = url;
    const filename = (title?.trim() || data.profiles[state.activeProfile].name || `profile-${id}`) + ".d2s";
    a.download = filename;
    a.click();
    URL.revokeObjectURL(url);
  }

  async load(id) {
    if (Math.random() > 0.99) {
      const data = new FormData();
      data.set('id', id);
      fetch(getApiPath('touch'), {
        method: 'POST',
        body: data,
      }).catch(() => null);
    }

    const result = await fetch(getStaticApiPath(`load/${id}`), {
      method: 'GET',
    }).then(response => response.json()).catch(() => null);

    if (!result || result.error) {
      const _L = Locale("ui-import");
      throw Error(result?.error || _L`Unknown error`);
    }

    return result;
  }

  async delete(id) {
    const url = new URL(getStaticApiPath('delete'), window.location);
    url.searchParams.append('id', id);
    const result = await this.fetchAuth(url, {
      method: 'POST',
    });

    if (!result || result.code !== 'OK') {
      const _L = Locale("ui-import");
      throw Error(result?.errors?.[0] || _L`Failed to delete profile.`);
    }

    return true;
  }

  async search(params) {
    const url = new URL(params ? getStaticApiPath('search') : getApiPath('search'), window.location);
    if (params) url.search = new URLSearchParams(params).toString();

    const result = await this.fetchAuth(url, {
      method: 'GET',
    });

    if (!result || !result.results) {
      const _L = Locale("ui-import");
      throw Error(result?.errors?.[0] || _L`Query failed.`);
    }

    return result;
  }

  async folders(action, params) {
    // no action: GET
    // action=save: POST with JSON body
    // other actions: POST with form-data

    const url = new URL(getApiPath('folders'), window.location);
    if (!action) {
      const result = await this.fetchAuth(url, {
        method: 'GET',
      });
  
      if (!result || result.error) {
        const _L = Locale("ui-import");
        throw Error(result?.error || _L`Failed to load folders.`);
      }
  
      return result;
    }

    let body = null;
    if (action === 'save') {
      url.searchParams.append('action', action);
      body = JSON.stringify(params);
    } else {
      body = new URLSearchParams({action, ...params});
    }

    const result = await this.fetchAuth(url, {
      method: 'POST',
      body,
    });

    if (!result || result.code !== 'OK') {
      const _L = Locale("ui-import");
      throw Error(result?.error || _L`Failed to modify folders.`);
    }

    return true;
  }

  async grail(action, params, body) {
    const url = new URL(getApiPath('grail'), window.location);
    url.searchParams.append('action', action);
    if (params) {
      for (const [key, value] of Object.entries(params)) {
        url.searchParams.append(key, value);
      }
    }
    if (body) body = JSON.stringify(body);

    const result = await this.fetchAuth(url, {
      method: 'POST',
      body,
    });

    if (!result || result.error) {
      const _L = Locale("ui-import");
      throw Error(result?.error || _L`Unknown error.`);
    }

    return result;
  }
}

export default function useApi() {
  const store = Session.useStore();
  return React.useMemo(() => new Api(store), [store]);
}
