}\n      .d2p-save-name {\n        width: 350px;\n      }\n\n      .d2p-save-options {\n        margin: 0.5em 0;\n      }\n\n      .d2p-save-folder {\n        font-size: $font-size;\n        margin-top: -2px;\n        margin-right: 0.5em;\n        width: 180px;\n        .ui-Select-value {\n          padding: 2px 16px 2px 8px;\n        }\n        .ui-Select-option {\n          padding: 2px 4px;\n        }\n      }\n      select {\n        font-size: $font-size;\n        margin-top: -2px;\n        vertical-align: middle;\n      }\n\n      .d2p-search-class, .d2p-search-set {\n        font-size: 0.9em;\n        padding: 2px;\n      }\n      .d2p-search-set {\n        width: 220px;\n        text-overflow: ellipsis;\n      }\n    }\n\n    .d2p-import-error {\n      font-size: 1.2em;\n    }\n\n    .d2p-save-status {\n      input {\n        width: 404px;\n        background-color: $color-bg;\n      }\n      font-size: 1.2em;\n    }\n\n    .d2p-import-header {\n      margin: 0.4em 0;\n    }\n    .d2p-import-tag {\n      font-size: 1.4em;\n    }\n    .d2p-import-hash {\n      font-size: 1.1em;\n      color: main-color(60%);\n    }\n    .d2p-import-guild {\n      font-size: 1.3em;\n      color: brand-fg(50%);\n    }\n\n    .d2p-search-results {\n      a, li {\n        display: block;\n        clear: both;\n        cursor: pointer;\n        padding: 1px;\n        &:hover {\n          background-color: brand-bg(50%);\n        }\n      }\n      .d2p-hero-dead .d2p-class-icon {\n        opacity: 0.7;\n      }\n      .d2p-class-icon {\n        display: inline-block;\n        font-size: 24px;\n        margin-right: 2px;\n      }\n      .d2p-hero-name {\n        font-size: 1.2em;\n        margin-right: 0.3em;\n      }\n      .d2p-hero-hardcore {\n        color: red;\n      }\n      .d2p-hero-death {\n        color: red;\n      }\n      .d2p-hero-updated {\n        color: main-color(50%);\n      }\n      .d2p-hero-death, .d2p-hero-updated {\n        line-height: 24px;\n        float: right;\n      }\n\n      .d2p-profile-name {\n        font-size: 1.1em;\n        position: relative;\n        line-height: 24px;\n        &.d2p-unnamed, .d2p-profile-author {\n          color: main-color(50%);\n        }\n      }\n      .d2p-profile-saved {\n        float: right;\n        position: relative;\n        width: 0;\n        z-index: 2;\n        line-height: 24px;\n        span {\n          display: block;\n          position: absolute;\n          right: 0;\n          white-space: nowrap;\n          background-color: rgba($color-bg-tabs, 0.8);\n          box-shadow: -10px 0 5px rgba($color-bg-tabs, 0.8);\n        }\n      }\n      a:hover {\n        .d2p-profile-name {\n          z-index: 4;\n          background-color: brand-bg(50%);\n          box-shadow: 10px 0 5px brand-bg(50%);\n        }\n        .d2p-profile-saved span {\n          background: none;\n          box-shadow: none;\n        }\n      }\n    }\n\n    &.d2p-section-search .d2p-search-results {\n      margin: 0.5em 0;\n    }\n\n    .d2p-search-nav {\n      font-size: 1.1em;\n      .d2p-nav-buttons {\n        float: right;\n        span, select {\n          margin: 0 6px;\n        }\n        span {\n          @include link-like;\n          font-size: 1.2em;\n          &.d2p-disabled {\n            cursor: default;\n            color: main-color(50%);\n            text-decoration: none;\n          }\n        }\n      }\n    }\n  }\n\n  .d2p-Autocomplete {\n    display: inline-block;\n    position: relative;\n    input {\n      width: 100%;\n    }\n    .d2p-options {\n      position: absolute;\n      z-index: 10;\n      left: 0;\n      top: 100%;\n      right: 0;\n      border: 1px solid $color-border;\n      background-color: $color-bg-contrast;\n      li {\n        padding: 0 4px;\n        cursor: pointer;\n      }\n      li:hover {\n        background-color: #3875d7;\n        background-image: linear-gradient(#3875d7 20%, #2a62bc 90%);\n        color: #fff;  \n      }\n    }\n  }\n\n  .d2p-ErrorBox {\n    position: absolute;\n    left: 50%;\n    top: 50%;\n    transform: translate(-50%, -50%);\n    border: 1px solid #f00;\n    background-color: #fcc;\n    color: #f00;\n    padding: 8px;\n    text-align: center;\n    h3 {\n      margin: 0;\n      font-size: 100%;\n      font-weight: bold;\n    }\n    p {\n      margin: 0;\n    }\n  }\n\n  .d2p-MyProfiles {\n    .d2p-profiles-view {\n      margin-bottom: 0.5em;\n      display: flex;\n      flex-direction: row;\n      height: 400px;\n    }\n    .d2p-loading {\n      color: main-color(50%);\n    }\n    .d2p-folders {\n      flex: 0 0 auto;\n      position: relative;\n      min-width: 100px;\n      max-width: 300px;\n      width: 180px;\n      &.d2p-expanding {\n        transition: width 250ms ease-out;\n        min-width: 0;\n      }\n      &.d2p-collapsed {\n        transition: width 250ms ease-out;\n        min-width: 0;\n        width: 10px !important;\n      }\n      .d2p-folder-list {\n        background-color: $color-bg;\n        position: absolute;\n        top: 0;\n        left: 0;\n        bottom: 0;\n        right: 10px;\n        padding: 0.3em 0;\n        border-top: 1px solid main-color(20%);\n        border-bottom: 1px solid main-color(20%);\n        border-left: 1px solid main-color(20%);\n        opacity: 1;\n        transition: opacity 250ms ease-out;\n        overflow-x: hidden;\n        overflow-y: auto;\n        white-space: nowrap;\n        user-select: none;\n\n        ul {\n          padding-left: 0.5em;\n        }\n        li {\n          padding-left: 0.3em;\n        }\n        .d2p-icon {\n          display: inline-block;\n          width: 16px;\n        }\n        div .d2p-label {\n          cursor: pointer;\n        }\n        .d2p-empty .d2p-label {\n          color: main-color(50%);\n        }\n        .d2p-active .d2p-label {\n          color: $brand-color;\n          cursor: grab;\n          &:active {\n            cursor: grabbing;\n          }\n        }\n        .d2p-active.d2p-root .d2p-label {\n          cursor: default;\n        }\n        .d2p-dragging .d2p-label {\n          color: main-color(50%);\n        }\n        .d2p-modify {\n          display: none;\n          margin-left: 0.4em;\n          font-size: 0.8em;\n          color: main-color(60%);\n          cursor: pointer;\n          &:hover {\n            color: $color-fg;\n          }\n        }\n        /*.d2p-active .d2p-modify {\n          color: brand-bg(40%);\n          &:hover {\n            color: $brand-color;\n          }\n        }*/\n        div:hover .d2p-modify {\n          display: inline;\n        }\n        input {\n          width: 100%;\n          max-width: 100px;\n          border: none;\n          box-shadow: none;\n          background-color: mix($color-bg, $color-bg-contrast, 75%);\n          padding: 0;\n        }\n        .d2p-create {\n          cursor: pointer;\n        }\n      }\n      &.d2p-collapsed .d2p-folder-list {\n        border-left-color: transparent;\n        opacity: 0;\n      }\n      .d2p-toggle {\n        position: absolute;\n        top: 0;\n        right: 2px;\n        bottom: 0;\n        width: 8px;\n        background-color: main-color(20%);\n        cursor: pointer;\n        color: $brand-color;\n        line-height: 400px;\n        font-size: 0;\n        & > * {\n          font-size: 30px;\n          vertical-align: middle;\n          transform: translateX(-3px) rotate(180deg);\n          transition: transform 250ms ease-out;\n        }\n      }\n      &.d2p-collapsed .d2p-toggle > * {\n        transform: none;\n      }\n    }\n    .d2p-status {\n      margin: 0.5em 0;\n      font-size: 1.1em;\n      input, textarea {\n        font-size: 1.2em;\n        padding: 1px 4px;\n        width: 100%;\n      }\n    }\n\n    .d2p-profiles {\n      flex: 1 1 auto;\n      background-color: $color-bg;\n      min-width: 0;\n      padding: 0.5em;\n\n      overflow-x: hidden;\n      overflow-y: auto;\n      border: 1px solid main-color(20%);\n      border-left-width: 0;\n      margin-left: -2px;\n\n      li {\n        display: block;\n        clear: both;\n        height: 20px;\n        &.d2p-active {\n          background-color: brand-bg(50%);\n        }\n\n        input {\n          width: 70%;\n          border: none;\n          box-shadow: none;\n          background-color: mix($color-bg, $color-bg-contrast, 75%);\n          padding: 0;\n        }\n      }\n\n      .d2p-class-icon {\n        display: inline-block;\n        font-size: 20px;\n        margin-right: 2px;\n      }\n      .d2p-profile-name {\n        font-size: 1.1em;\n        position: relative;\n        line-height: 20px;\n        &.d2p-unnamed, .d2p-profile-author {\n          color: main-color(50%);\n        }\n      }\n      .d2p-profile-saved {\n        float: right;\n        position: relative;\n        z-index: 2;\n        line-height: 20px;\n        .d2p-date {\n          display: block;\n          position: absolute;\n          right: 0;\n          top: 0;\n          height: 18px;\n          white-space: nowrap;\n          background-color: rgba($color-bg, 0.8);\n          box-shadow: -10px 0 5px rgba($color-bg, 0.8);\n          color: main-color(70%);\n        }\n      }\n      .d2p-modify {\n        position: relative;\n        z-index: 10;\n        display: none;\n        top: 2px;\n        height: 16px;\n        font-size: $font-size;\n        color: main-color(70%);\n        > span {\n          margin: 0 0.3em;\n          cursor: pointer;\n          &:hover {\n            color: $color-fg;\n          }\n        }\n      }\n      li.d2p-active .d2p-date {\n        background-color: rgba(brand-bg(50%), 0.8);\n        box-shadow: -10px 0 5px rgba(brand-bg(50%), 0.8);\n      }\n      li:hover, li.d2p-renaming {\n        .d2p-modify {\n          display: inline-block;\n        }\n        .d2p-date {\n          display: none;\n        }\n      }\n    }\n  }\n}\n","$color-bg-dark: #000;\n$color-bg: #181818;\n$color-fg: #eee;\n$color-bg-contrast: #000;\n$color-fg-contrast: #fff;\n\n$color-bg-tabs: #202020;\n\n$color-border: #242424;\n$color-border-tabs: #303030;\n\n//$color-bg-dark: #ddd;\n//$color-bg: #ddd;\n//$color-fg: #222;\n//$color-fg-contrast: #000;\n//$color-bg-contrast: #fff;\n//$color-bg-tabs: #eee;\n\n$color-link: #057af0;\n$color-active: #057af0;\n$brand-color: #057af0;\n\n$font-family: 'Source Sans Pro', 'Verdana', 'Arial', sans-serif;\n$font-size: 14px;\n","@import 'theme';\n\n@function main-color($amount) {\n  @return mix($color-fg, $color-bg, $amount);\n}\n@function bg-color($amount) {\n  @return mix($color-bg, $color-bg-dark, $amount);\n}\n@function brand-bg($amount) {\n  @return mix($color-bg, $brand-color, $amount);\n}\n@function brand-fg($amount) {\n  @return mix($color-fg, $brand-color, $amount);\n}\n@function abs-color($amount) {\n  @return mix($color-fg-contrast, $color-bg-contrast, $amount);\n}\n\n@mixin link-like {\n  color: $color-link;\n  cursor: pointer;\n  &:hover {\n    text-decoration: underline;\n  }\n}\n\n$d2-color-0: #ffffff;\n$d2-color-1: #ff4d4d;\n$d2-color-2: #00ff00;\n$d2-color-3: #6969ff;\n$d2-color-4: #c7b377;\n$d2-color-5: #797979;\n$d2-color-6: #000000;\n$d2-color-7: #d0c27d;\n$d2-color-8: #ffa800;\n$d2-color-9: #ffff64;\n$d2-color-10: #008000;\n$d2-color-11: #ae00ff;\n$d2-color-12: #00c800;\n"],"sourceRoot":""}]);
