class DualWieldCalculator {
  constructor(stats, mainhand, offhand, average) {
    this.mainhand = mainhand;
    this.offhand = offhand;
    this.average = average;

    mainhand.wsmlist = [mainhand.wsm];
    offhand.wsmlist = [offhand.wsm];
    this.hits = 1;
    this.type = 'oias';

    if (average) {
      this.foinames = ['frames'];
    } else {
      this.foinames = ['r1'];
      if (mainhand.foinames.length > 1) this.foinames.push('r2');
      this.foinames.push('l1', 'average');
    }

    // accel = off-weapon IAS for us
    this.minaccel = 0;
    this.maxaccel = 9999;
  }

  calculate() {
    if (!this.mainhand.calculate()) return null;
    if (!this.offhand.calculate()) return null;

    if (this.average) {
      this._combine = (mh, oh) => [Math.ceil((mh[mh.length - 1] + oh[oh.length - 1]) / 2)];
    } else {
      this._combine = (mh, oh) => {
        const out = mh.slice();
        if (out.length > 1) out.pop();
        out.push(oh[0], (mh[mh.length - 1] + oh[0]) / 2);
        return out;
      };
    }

    const weapon = this.mainhand.weapon;
    this.accel = (weapon.item_fasterattackrate || 0) - (weapon.weaponias || 0);
    this.result = this._combine(this.mainhand.result, this.offhand.result);
    this.fpa = this.result[this.result.length - 1];
    return this;
  }

  fullTable() {
    const getTable = wpn => wpn.fullTable(wpn.weapon.weaponias || 0)[1].filter(row => row.params[0] >= 0);
    const t1 = getTable(this.mainhand);
    const t2 = getTable(this.offhand);

    const result = [];
    let i1 = 0, i2 = 0;
    while (i1 < t1.length && i2 < t2.length) {
      const n1 = (i1 + 1 < t1.length ? t1[i1 + 1].params[0] : Infinity);
      const n2 = (i2 + 1 < t2.length ? t2[i2 + 1].params[0] : Infinity);
      const ias = Math.max(t1[i1].params[0], t2[i2].params[0]);
      result.push({
        frames: this._combine(t1[i1].frames, t2[i2].frames),
        minaccel: ias,
        maxaccel: Math.min(n1, n2) - 1,
        params: [ias],
      });
      if (n1 === n2) {
        i1 += 1;
        i2 += 1;
      } else if (n1 < n2) {
        i1 += 1;
      } else {
        i2 += 1;
      }
    }

    return [this.foinames, result];
  }

  weaponList() {
    return [];
  }
}
export class RollbackAnimationCalculator extends AnimationCalculator {
  init2(hits, rollback) {
    const {data, sequence, start, wereformFactor} = this;

    this.hits = hits;
    this.foinames = [...Array(hits)].map((_, i) => `hit${i + 1}`);
    this.foinames.push('total');

    const af = sequence ? sequence[1] : data[2];
    if (!af || af < 0) return false;
    const frames = sequence ? sequence[0] : data[0];

    this._frames = accel => {
      let pos = start;
      const result = [];
      let total = 0;
      let step = Math.floor(this.speed * accel / 100);
      if (wereformFactor) step = Math.floor(step * wereformFactor);
      for (let i = 0; i < hits - 1; ++i) {
        const cur = Math.ceil(256 * (af - pos) / step);
        result.push(cur);
        total += cur;
        pos = Math.floor(Math.floor((256 * pos + cur * step) / 256) * (100 - rollback) / 100);
      }
      const last = Math.ceil(256 * (frames - pos) / step) - (this.mode === 'SQ' ? 0 : 1);
      total += last;
      result.push(last, total);
      return result;
    };
    this.compress = hits;

    return true;
  }
}

const makeWereformCalculator = Base => class WereformCalculator extends Base {
  init(...params) {
    const {unit, stats, skill, wclass} = this;

    let mode = this.mode = skill.anim;
    if (mode === 'SQ') {
      const seq = animSequences[skill.seqnum];
      if (seq) {
        this.type = seq.type;
        this.sequence = seq.data[animWeapons.indexOf(wclass)] || seq.data[0];
        if (!this.sequence) return false;
      }
      mode = 'GH';
    } else {
      this.type = animTypes[mode];
    }
    if (this.type !== 'ias') return false;

    this.type = 'wias2';

    const data = this.data = Data.animData(`${unit}${mode}${wclass.toUpperCase()}`) || Data.animData(`${unit}${mode}HTH`);
    if (!data) return false;

    const weapon = this.weapon = (skill.weapsel === 1 && stats.weapon2) || stats.weapon1;
    this.wsm = weapon.weaponspeed;
    let baseaccel = 100 + (weapon.attackrate || 0) - this.wsm;
    if (this.mode === 'SQ') {
      baseaccel -= 30;
    }
    this.wsmlist = [this.wsm];

    this.minaccel = 0;
    this.maxaccel = 120;
    this.accel = this.weapon.weaponias || 0;

    this.speed = data[1];
    this.start = startFrame(unit, mode, wclass);

    this.init2(...params);

    const _oframes = this._frames;

    const wclass1 = Data.items[weapon.baseitem]?.wclass?.toUpperCase() || 'HTH';
    const human = playerCode[this.stats.class];
    const humanData = Data.animData(`${human}A1${wclass1}`) || Data.animData(`${human}A1HTH`);
    const neutral = Data.animData(`${unit}NUHTH`);
    const oias = (weapon.item_fasterattackrate || 0) - (weapon.weaponias || 0);
    if (!humanData || !neutral) return null;

    this._frames = wias => {
      const hframes = Math.floor(256 * humanData[0] / Math.floor(humanData[1] * (100 + wias - weapon.weaponspeed) / 100));
      this.speed = Math.floor(256 * neutral[0] / hframes);
      const dr_accel = 120 * (wias + oias) / (120 + wias + oias) | 0;
      const accel = Math.max(15, Math.min(175, baseaccel + dr_accel));
      return _oframes(accel);
    };

    return true;
  }

  calculate() {
    if (this.error) return null;

    this.result = this._frames(this.accel);
    this.fpa = this.result[this.result.length - 1];

    const minResult = this._frames(this.minaccel);
    const maxResult = this._frames(this.maxaccel);
    if (minResult.every((v, i) => v === maxResult[i])) {
      this.maxaccel = this.minaccel;
    }

    return this;
  }

  reqparams(minaccel, maxaccel, delta=0) {
    if (maxaccel < 0) return [-1];
    return [Math.max(minaccel, 0)];
  }
};

class WhirlwindCalculator extends AnimationCalculator {
  init(weapon) {
    this.weapon = weapon;
    const wclass = this.wclass = Data.items[weapon.baseitem]?.wclass || 'hth';
    this.mode = 'A1';
    this.type = 'ias';

    let data = [7, 256];
    if (wclass === '2ht' || wclass === 'stf') {
      data = [9, 256];
    } else if (wclass === 'ht1') {
      data = [6, 208];
    }

    this.speed = data[1];

    this.wsm = weapon.weaponspeed;
    this.baseaccel = 100 - this.wsm;
    this.varaccel = weapon.weaponias || 0;

    const wc = weaponClassTag(Data.items[weapon.baseitem]);
    this.weaponFilter = weaponFilterSkill(this.skill, wc);
    this.wsmlist = weaponSpeedList(this.weaponFilter, this.wsm);

    this.foinames = ['frames'];
    this.hits = 1;

    this._frames = accel => [Math.ceil(256 * data[0] / Math.floor(data[1] * accel / 100)) - 1];

    return true;
  }
}

const WereformCalculator = makeWereformCalculator(AnimationCalculator);
const WereformRollbackCalculator = makeWereformCalculator(RollbackAnimationCalculator);

const bpMode = {fbr: 'BL', fcr: 'SC', fhr: 'GH'};
export function breakpointList(stats, type) {
  const calc = new AnimationCalculator(stats, {anim: bpMode[type]});
  if (type === 'fbr' && stats.base.state?.[101]) { // holy shield
    calc.baseaccel += 50;
  }
  if (!calc.calculate()) return null;

  return {values: calc.simpleTable(), current: calc.fpa, title: `${calc.unitName} / ${calc.wclass.toUpperCase()}`};
}

export function basicAttackCalculator(stats, skill) {
  const mainhand = new MainHandCalculator(stats, skill);
  if (Data.info.patch && mainhand.wereform) {
    return new AnimationCalculator(stats, skill);
  }
  if (stats.weapon2 && !mainhand.wereform && !mainhand.error) {
    return new DualWieldCalculator(stats, mainhand, new OffHandCalculator(stats));
  }
  return mainhand;
}

export function whirlwindCalculator(stats, skill) {
  const mainhand = new WhirlwindCalculator(stats, skill, stats.weapon1);
  if (stats.weapon2 && !mainhand.error) {
    return new DualWieldCalculator(stats, mainhand, new WhirlwindCalculator(stats, skill, stats.weapon2), true);
  }
  return mainhand;
}

export function defaultAnimation(skill, stats) {
  const anim = new AnimationCalculator(stats, skill);
  //if (!anim.type) return; // no scaling - pointless to display
  return anim.calculate();
}
