function formatStat(stat, min, max, param) {
  let src = acronyms[stat];
  if (!src) return;
  if (min === max) src = src.replace('$1-$2', '$1');
  src = _L(src);
  return src.replace(/\$[012*]/g, sym => {
    if (sym === '$1') {
      return min;
    } else if (sym === '$2') {
      return max;
    } else if (sym === '$*') {
      return (min === 1 ? '' : min + ' ');
    } else {
      switch (stat) {
      case 'item_addclassskills': return _L(acronym_class[param] || '');
      case 'item_elemskill': return _L`fire sk`;
      case 'item_addskill_tab': return _L(acronym_tab[param] || '');
      default:
        const skill = Data.skills[param];
        const skilldesc = skill && Data.skillDesc[skill.skilldesc];
        return Locale.strings[skilldesc?.strname]?.toLowerCase() || '';
      }
    }
  });
}

export function formatRBF(item) {
  const uniq = Data.uniqueItems[item.unique];
  if (!uniq) return;
  let name;
  switch (uniq.prop1) {
  case 'dmg-ltng': name = 'light'; break;
  case 'dmg-cold': name = 'cold'; break;
  case 'dmg-fire': name = 'fire'; break;
  case 'dmg-pois': name = 'psn'; break;
  default: return;
  }
  name += (uniq.prop4 === 'death-skill' ? ' die' : ' up');
  const val = item.uniqueValues;
  if (!val) return name;
  return `${_L(name)} -${val[1]}/+${val[2]}`;
}
function formatTorch(item) {
  const val = item.uniqueValues || [];
  return `${_L(acronym_class[val[0]])} ${val[1]}/${val[2]}`;
}
function formatAnni(item) {
  const val = item.uniqueValues || [];
  return `${val[1]}/${val[2]}/${val[3]}`;
}

export function itemCreateDescription(item, stats, fixedStats) {
  if (item.quality === Quality.UNIQUE) {
    if (item.base === 'jew') return formatRBF(item);
    if (item.base === 'cm2') return formatTorch(item);
    if (item.base === 'cm1') return formatAnni(item);
  }

  const base = Data.items[item.base];
  if (!base) return null;

  if (item.quality === Quality.RUNEWORD) {
    delete stats.item_numsockets;
  } else if (item.sockets) {
    stats.item_numsockets = item.sockets - (item.socketedItems?.length || 0);
  }

  if (fixedStats) {
    for (const id in fixedStats) {
      if (stats[id] && fixedStats[id] < stats[id]) {
        stats[id] -= fixedStats[id];
      } else if (fixedStats[id] === stats[id]) {
        delete stats[id];
      }
    }
  }

  const lines = [];

  if (stats.strength && stats.energy === stats.strength && stats.dexterity === stats.strength && stats.vitality === stats.strength) {
    lines.push([Data.itemStatCost.energy.descpriority, formatStat('meta_allstats', stats.strength)]);
    delete stats.strength;
    delete stats.energy;
    delete stats.dexterity;
    delete stats.vitality;
  }

  if (stats.fireresist && stats.lightresist === stats.fireresist && stats.coldresist === stats.fireresist && stats.poisonresist === stats.fireresist) {
    lines.push([Data.itemStatCost.poisonresist.descpriority, formatStat('meta_allres', stats.fireresist)]);
    delete stats.fireresist;
    delete stats.lightresist;
    delete stats.coldresist;
    delete stats.poisonresist;
  }

  if (stats.mindamage && stats.maxdamage) {
    lines.push([Data.itemStatCost.maxdamage.descpriority, formatStat('meta_dmgrange', stats.mindamage, stats.maxdamage)]);
    delete stats.mindamage;
    delete stats.maxdamage;
  }

  if (stats.firemindam && stats.firemaxdam) {
    lines.push([Data.itemStatCost.firemaxdam.descpriority, formatStat('meta_firerange', stats.firemindam, stats.firemaxdam)]);
    delete stats.firemindam;
    delete stats.firemaxdam;
  }

  if (stats.coldmindam && stats.coldmaxdam) {
    lines.push([Data.itemStatCost.coldmaxdam.descpriority, formatStat('meta_coldrange', stats.coldmindam, stats.coldmaxdam)]);
    delete stats.coldmindam;
    delete stats.coldmaxdam;
    delete stats.coldlength;
  }

  if (stats.lightmindam && stats.lightmaxdam) {
    lines.push([Data.itemStatCost.lightmaxdam.descpriority, formatStat('meta_lightrange', stats.lightmindam, stats.lightmaxdam)]);
    delete stats.lightmindam;
    delete stats.lightmaxdam;
  }

  if (stats.magicmindam && stats.magicmaxdam) {
    lines.push([Data.itemStatCost.magicmaxdam.descpriority, formatStat('meta_magicrange', stats.magicmindam, stats.magicmaxdam)]);
    delete stats.magicmindam;
    delete stats.magicmaxdam;
  }

  if (stats.poisonmindam && stats.poisonmaxdam && stats.poisonlength) {
    let length = stats.poisonlength;
    if (stats.poison_count) length /= stats.poison_count;
    lines.push([Data.itemStatCost.poisonmaxdam.descpriority, formatStat('meta_poisonrange', Math.round(stats.poisonmindam * length / 256), Math.round(stats.poisonmaxdam * length / 256))]);
    delete stats.poisonmindam;
    delete stats.poisonmaxdam;
    delete stats.poisonlength;
    delete stats.poison_count;
  }

  if (stats.item_mindamage_percent && stats.item_maxdamage_percent === stats.item_mindamage_percent) {
    lines.push([Data.itemStatCost.item_mindamage_percent.descpriority, formatStat('meta_dmgpercent', stats.item_mindamage_percent)]);
    delete stats.item_mindamage_percent;
    delete stats.item_maxdamage_percent;
  }

  for (const idFull in stats) {
    let [id, param, param2] = idFull.split('#');
    const stat = Data.itemStatCost[id];
    if (!stat || !acronyms[id]) continue;
    let value = stats[idFull];
    if (!value && param2 !== 'x') continue;
    let priority = stat.descpriority;
    if (param) priority += parseInt(param) * 0.000001;
    if (param2 === 'x') {
      param2 = param;
      param = value;
      value = param2;
      param2 = null;
    }

    switch (stat.descfunc) {
    case 5: case 10:
      value *= 100 / 128;
      break;
    case 11: // Repairs 1 Durability In [100 / value] Seconds
      value = 100 / value;
      break;
    case 20:
    case 21:
      value = -value;
      break;
    // no default
    }
    if (stat.descfunc >= 6 && stat.descfunc <= 10) {
      value = parseFloat((value / (1 << stat.opparam)).toFixed(3));
    } else if (typeof value === 'number') {
      value = value.toFixed(0);
    }
    lines.push([priority, formatStat(id, value, param2, param)]);
  }

  const defRange = itemDefenseRange(item);
  if (defRange && defRange.minac < defRange.maxac && item.defense) {
    let def = item.defense;
    if (item.ethereal || item.stats?.item_ethereal) {
      def += Math.floor(def * 0.5);
      if (item.ethbugged) def += Math.floor(def * 0.5);
    }
    if (item.quality === Quality.LOW) {
      def = Math.floor(def * 0.75);
    }
    if (item.stats.item_armor_percent) {
      def += (def * (item.stats.item_armor_percent || 0) / 100) | 0;
    }
    if (item.stats.armorclass) {
      def += item.stats.armorclass;
    }
    lines.push([1000, formatStat('meta_totaldef', def)]);
  }

  if (item.ethereal) {
    if (item.ethbugged) {
      lines.push([0, formatStat('meta_ethbugged', 1)]);
    } else {
      lines.push([0, formatStat('meta_ethereal', 1)]);
    }
  }

  return lines.sort((a, b) => b[0] - a[0]).map(line => line[1]).join(' ');
}

export function itemGetDescription(item, items) {
  if (!items || item.quality === Quality.RUNEWORD || !item.socketedItems?.length) return item.description;
  return [
    item.description,
    ...item.socketedItems.map(id => {
      const gem = Data.gems[id];
      if (gem) {
        return gem.letter ? gem.letter.toLowerCase() : _L(acronym_gem[id] || '');
      } else {
        return items[id]?.description;
      }
    })
  ].filter(Boolean).join(' + ');
}
