function baseFilter(type, func) {
  switch (type) {
  case 'normal': return { filter: id => func(Data.items[id]) };
  case 'crafted': return { base: base => func(Data.items[base]) };
  case 'runeword': return { base: base => func(Data.items[base]) };
  case 'unique': return { filter: id => func(Data.items[Data.uniqueItems[id]?.code]) };
  case 'set': return { filter: id => func(Data.items[Data.setItems[id]?.item]) };
  // no default
  }
}

const checkNumber = (stat, min, max) => (min == null || stat >= min) && (max == null || stat <= max);

