function checkMod(mod, types, rare) {
  if (mod.level > 99) return false;
  if (![mod.itype1, mod.itype2, mod.itype3, mod.itype4, mod.itype5, mod.itype6, mod.itype7].some(t => t && types.has(t))) return false;
  if ([mod.etype1, mod.etype2, mod.etype3, mod.etype4, mod.etype5].some(t => t && types.has(t))) return false;
  if (!mod.rare && rare) return false;
  return true;
}

let statCache = null;

function modMaxStats(id, mod) {
  const values = [];
  if (mod.mod1max != null) values[0] = mod.mod1max;
  if (mod.mod2max != null) values[1] = mod.mod2max;
  if (mod.mod3max != null) values[2] = mod.mod3max;
  if (mod.mod4max != null) values[3] = mod.mod4max;
  return modsToStats({}, {[id]: values});
}

function initCache() {
  if (!statCache) {
    const groups = {};
    for (const [id, mod] of Object.entries({...Data.magicPrefix, ...Data.magicSuffix})) {
      const stats = modMaxStats(id, mod);
      groups[mod.group] = groups[mod.group] || [];
      groups[mod.group].push({mod, stats});
    }
    statCache = Object.values(groups);
  }
}

function statFilter(type, func) {
  initCache();

  switch (type) {
  case 'normal':
    return {type(type) {
      const types = extendType(new Set(), type);
      const groups = statCache.map(g => g.filter(({mod}) => checkMod(mod, types)));
      return func(id => groups.reduce((sum, g) => sum + g.reduce((max, {stats}) => Math.max(max, stats[id] || 0), 0), 0));
    }};
  case 'crafted':
    return {type(id, type) {
      const recipe = Data.crafted[id];
      const stats = modMaxStats(id, recipe);

      const types = extendType(new Set(), type);
      const groups = statCache.map(g => g.filter(({mod}) => checkMod(mod, types, true)));
      return func(id => groups.reduce((sum, g) => sum + g.reduce((max, {stats}) => Math.max(max, stats[id] || 0), 0), stats[id] || 0));
    }};
  case 'unique':
  case 'set':
    return {filter(uniq) {
      const item = Data.uniqueItems[uniq] || Data.setItems[uniq];
      const values = [];
      for (let i = 1; i <= 12; ++i) {
        if (item[`max${i}`]) values[i - 1] = item[`max${i}`];
      }
      const stats = uniqueStats({}, item, values);
      return func(id => stats[id] || 0);
    }};
  case 'runeword':
    return {filter(rw, type) {
      const rune = Data.runes[rw];
      const values = [];
      for (let i = 1; i <= 7; ++i) {
        if (rune[`t1max${i}`]) values[i - 1] = rune[`t1max${i}`];
      }
      const stats = runewordStats({}, rune, values);
      const types = new Set([type]);
      for (let i = 1; i <= 6; ++i) {
        if (rune[`rune${i}`]) gemStats(stats, rune[`rune${i}`], types);
      }
      return func(id => stats[id] || 0);
    }};
  // no default
  }
}

function statFilterParam(type, id) {
  initCache();

  id += '#';

  switch (type) {
  case 'normal':
    return {type(type) {
      const types = extendType(new Set(), type);
      return statCache.some(g => g.some(({mod, stats}) => checkMod(mod, types) && Object.keys(stats).some(stat => stat.includes(id))));
    }};
  case 'crafted':
    return {type(id, type) {
      const recipe = Data.crafted[id];
      const stats = modMaxStats(id, recipe);
      if (Object.keys(stats).some(stat => stat.includes(id))) return true;

      const types = extendType(new Set(), type);
      return statCache.some(g => g.some(({mod, stats}) => checkMod(mod, types, true) && Object.keys(stats).some(stat => stat.includes(id))));
    }};
  case 'unique':
  case 'set':
    return {filter(uniq) {
      const item = Data.uniqueItems[uniq] || Data.setItems[uniq];
      const values = [];
      for (let i = 1; i <= 12; ++i) {
        if (item[`max${i}`]) values[i - 1] = item[`max${i}`];
      }
      const stats = uniqueStats({}, item, values);
      return Object.keys(stats).some(stat => stat.includes(id));
    }};
  case 'runeword':
    return {filter(rw) {
      const rune = Data.runes[rw];
      const values = [];
      for (let i = 1; i <= 7; ++i) {
        if (rune[`t1max${i}`]) values[i - 1] = rune[`t1max${i}`];
      }
      const stats = runewordStats({}, rune, values);
      return Object.keys(stats).some(stat => stat.includes(id));
    }};
  // no default
  }
}

const statFilterSingle = (name, id) => ({
  id,
  name,
  type: 'number',
  filter: (type, min, max) => statFilter(type, stats => checkNumber(stats(id), min, max)),
});

const statFilterBoolean = (name, id) => ({
  id,
  name,
  type: 'boolean',
  filter: (type, value) => statFilter(type, stats => !stats(id) === !value),
});

const statFilterPerLevel = (name, id, idlvl) => ({
  id,
  name,
  type: 'number',
  filter(type, min, max, param, state) {
    const mult = state.profiles[state.activeProfile].level / (1 << Data.itemStatCost[idlvl].opparam);
    return statFilter(type, stats => checkNumber(stats(id) + (stats(idlvl) * mult | 0), min, max));
  },
});

