export function createItemFilter(filter = [], base = [], type = []) {
  const func = list => ((...args) => list.every(f => !f || f(...args)));
  return {
    funcs: {filter, base, type},
    filter: func(filter),
    base: func(base),
    type: func(type),
  };
}

export function itemFilterFunction(filters, type, state) {
  const filterFunc = filters.map(({id, min, max, param}) => itemFilters[id]?.filter(type, min, max, param, state)).filter(Boolean);
  if (!filterFunc.length) return;
  return createItemFilter(
    filterFunc.map(f => f.filter).filter(Boolean),
    filterFunc.map(f => f.base).filter(Boolean),
    filterFunc.map(f => f.type).filter(Boolean)
  );
}

