function ItemFilterLine({ value, onChange }) {
  const store = Store.useStore();

  const getOptions = React.useCallback(() => [
    {title: _L`Requirements`, options: itemFilterRequirements},
    {title: _L`Attributes`, options: itemFilterAttributes},
    {title: _L`Defenses`, options: itemFilterDefenses},
    {title: _L`Resistances`, options: itemFilterResistances},
    {title: _L`Damage`, options: itemFilterDamage},
    {title: _L`Offense`, options: itemFilterOffensive},
    {title: _L`Skills`, options: itemFilterSkills},
    {title: _L`Misc`, options: itemFilterMisc},
  ], []);

  const onChangeFilter = React.useCallback(value => {
    if (value) {
      const filter = itemFilters[value.id];
      const {min=1, max, param} = filter.defaultValue?.(store.getState()) || {};
      onChange({id: value.id, min, max, param});
    } else {
      onChange(null);
    }
  }, [store, onChange]);
  const onChangeMin = React.useCallback(e => onChange(value => ({...value, min: e.target.value ? parseInt(e.target.value) : null})), [onChange]);
  const onChangeMax = React.useCallback(e => onChange(value => ({...value, max: e.target.value ? parseInt(e.target.value) : null})), [onChange]);
  const onChangeBoolean = React.useCallback(opt => onChange(value => ({...value, min: parseInt(opt.id)})), [onChange]);
  const onChangeParam = React.useCallback(opt => onChange(value => ({...value, param: opt.id})), [onChange]);

  const info = value && itemFilters[value.id];
  const {noMinimum, noMaximum, type, paramType} = info || {};

  const valueRef = React.useRef();
  React.useEffect(() => valueRef.current?.focus(), [info]);

  const boolOptions = React.useMemo(() => [{id: '0', name: _L`No`}, {id: '1', name: _L`Yes`}], []);

  let values;
  if (type === 'number') {
    values = <>
      <input type="number" className="d2p-filter-min" min={info.min} max={info.max} value={noMinimum ? '' : value.min ?? ''}
        onChange={onChangeMin} ref={noMinimum ? null : valueRef} disabled={noMinimum} placeholder={_L`Min`}/>
      <span className="d2p-filter-dash"> {_L`to`} </span>
      <input type="number" className="d2p-filter-max" min={info.min} max={info.max} value={noMaximum ? '' : value.max ?? ''}
        onChange={onChangeMax} ref={noMinimum ? valueRef : null} disabled={noMaximum} placeholder={_L`Max`}/>
    </>;
  } else if (type === 'boolean') {
    values = <>
      <Select options={boolOptions}
              value={boolOptions[value.min ? 1 : 0]}
              onChange={onChangeBoolean}
              className="d2p-filter-min"
              />
      <span className="d2p-filter-dash"/>
      <span className="d2p-filter-max"/>
    </>;
  }

  return (<>
    <div className="d2p-ItemFilterLine">
      <Select options={getOptions}
              value={value && itemFilters[value.id]}
              onChange={onChangeFilter}
              searchLimit={10}
              className="d2p-filter-stat"
              allowEmpty/>
      {!paramType && values}
      {paramType === 'class' && (
        <Select options={classOptions}
                value={{id: value.param, name: Locale.strings[Data.classNames[Data.classes[value.param]]] || _L`Any Class`}}
                onChange={onChangeParam}
                className="d2p-filter-param"
                />
      )}
      {paramType === 'skilltab' && (
        <Select options={skilltabOptions}
                value={{id: value.param, name: skilltabName(value.param)}}
                onChange={onChangeParam}
                className="d2p-filter-param"
                searchLimit={10}
                />
      )}
      {(paramType === 'skill' || paramType === 'aura') && (
        <Select options={paramType === 'skill' ? skillOptions : auraOptions}
                value={{id: value.param, name: skillName(value.param)}}
                onChange={onChangeParam}
                className="d2p-filter-param"
                searchLimit={10}
                />
      )}
    </div>
    {!!(paramType && values && value.param !== -1) && (
      <div className="d2p-ItemFilterLine">
        <div className="d2p-filter-stat"/>
        {values}
      </div>
    )}
  </>);
}

export default function ItemFilterDialog({ onClose, onAccept, initialValue }) {
  const [filters, setFilters] = React.useState(initialValue);

  const onKeyDown = React.useCallback(e => {
    if (e.key === "Enter") {
      onAccept(filters);
    }
  }, [onAccept, filters]);

  const onChange = (index, value) => setFilters(filters => {
    filters = filters.slice();
    if (typeof value === 'function') value = value(filters[index]);
    if (value) {
      filters[index] = value;
    } else {
      filters.splice(index, 1);
    }
    return filters;
  });

  return (
    <Dialog title={_L`Filter items`} modal onClose={onClose} className="d2p-ItemFilterDialog" onKeyDown={onKeyDown}>
      <Dialog.Content>
        {[...filters, null].map((value, index) => <ItemFilterLine key={index} value={value} onChange={value => onChange(index, value)}/>)}
      </Dialog.Content>
      <Dialog.Footer>
        <button onClick={() => onAccept(filters)}>{_L`Filter`}</button>
        <button onClick={onClose}>{_L`Cancel`}</button>
      </Dialog.Footer>
    </Dialog>
  );
}
